  var Sprite2DFrag_default = '#include "ClipFrag.glsl";\n#include "Color.glsl";\n\n\nvec4 transspaceColor(vec4 color)\n{\n     \n #ifndef GAMMATEXTURE\n     //\u662Flinear\u6570\u636E\n     #ifdef GAMMASPACE\n         color.xyz = linearToGamma(color.xyz);    \n     #endif\n #else\n     //gamma\u6570\u636E\n     #ifndef GAMMASPACE\n         color.xyz = gammaToLinear(color.xyz);\n     #endif\n #endif\n     return color;\n }\n\n\n#ifdef TEXTUREVS\n    varying vec4 v_texcoordAlpha;\n    varying vec4 v_color;\n    varying float v_useTex;\n    varying float v_useClip;\n    varying vec4 v_customs;\n\n    //uniform\n    #ifdef USE_TEX_ARRAY\n        varying float v_texLayer;                 // \u6765\u81EA VS \u7684\u56FE\u5C42\u7D22\u5F15\n        uniform sampler2DArray u_spriteTextureArray;\n    #else\n        uniform sampler2D u_spriteTexture;\n    #endif\n\n    #ifdef FILLTEXTURE\n        uniform vec4 u_TexRange; // startu,startv,urange, vrange\n    #endif\n\n    vec4 getSpriteTextureColor(){\n        vec2 uv;\n        #ifdef FILLTEXTURE\n            uv = fract(v_texcoordAlpha.xy) * u_TexRange.zw + u_TexRange.xy;\n        #else\n            uv = v_texcoordAlpha.xy;\n        #endif\n\n        #ifdef USE_TEX_ARRAY\n            // WebGL2: \u4F7F\u7528 texture() \u91C7\u6837 2D Array\uFF08layer \u4E3A\u6D6E\u70B9\u6570\uFF0C\u5185\u90E8\u6309\u6574\u6570\u53D6\u5C42\uFF09\n            vec4 color = texture(u_spriteTextureArray, vec3(uv, v_texLayer));\n        #else\n            vec4 color = texture2D(u_spriteTexture, uv);\n        #endif\n        return transspaceColor(color);\n    }\n\n    void setglColor(in vec4 color){\n        // if(v_useTex <= 0.)\n        //     color = vec4(1., 1., 1., 1.);\n        float useTex = step(1.0, v_useTex);\n        color = color * useTex + (1.0 - useTex);\n\n        #ifdef UV_CLIP_GPU\n            if (v_useClip >= 1.0) {\n                vec2 uv = v_texcoordAlpha.xy;\n                vec4 c = v_customs;\n                if (uv.x < c.x || uv.x > c.x + c.z || uv.y < c.y || uv.y > c.y + c.w)\n                    discard;\n            }\n        #endif\n\n        color.a *= v_color.w;\n        vec4 transColor = v_color;\n        #ifndef GAMMASPACE\n            transColor = gammaToLinear(v_color);\n        #endif\n        color.rgb *= transColor.rgb;\n        gl_FragColor = color;\n    }\n#endif\n\n#ifdef BASERENDER2D\n    varying vec2 v_texcoord;\n    varying vec4 v_color;\n    uniform sampler2D u_baseRender2DTexture;\n    uniform vec4 u_baseRenderColor;\n    uniform vec4 u_tilingOffset;\n\n#ifdef LIGHT2D_ENABLE\n    varying vec2 v_lightUV;\n    uniform vec3 u_LightDirection;\n    uniform vec4 u_LightAndShadow2DParam;\n    uniform vec4 u_LightAndShadow2DAmbient;\n    uniform sampler2D u_LightAndShadow2D;\n    #ifdef LIGHT2D_SCENEMODE_ADD\n        uniform sampler2D u_LightAndShadow2D_AddMode;\n    #endif\n    #ifdef LIGHT2D_SCENEMODE_SUB\n        uniform sampler2D u_LightAndShadow2D_SubMode;\n    #endif\n\n    #ifdef LIGHT2D_NORMAL_PARAM\n        uniform sampler2D u_normal2DTexture;\n        uniform float u_normal2DStrength;\n    #endif\n\n    void lightAndShadow(inout vec4 color) {\n        #ifdef LIGHT2D_EMPTY //\u573A\u666F\u4E2D\u6CA1\u6709\u706F\u5149\uFF0C\u53EA\u6709\u73AF\u5883\u5149\u8D77\u4F5C\u7528\n            color.rgb *= u_LightAndShadow2DAmbient.rgb;\n        #else\n            vec2 uv = v_lightUV;\n            vec2 tt = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n            float side = tt.x * tt.y;\n            vec3 ambient = color.rgb * u_LightAndShadow2DAmbient.rgb; //\u73AF\u5883\u5149\u6210\u5206\n            color.rgb = color.rgb * texture2D(u_LightAndShadow2D, uv).rgb * side; //\u573A\u666F\u548C\u706F\u5149\u76F8\u4E58\u6A21\u5F0F\n            side *= color.a; //Alpha\u9884\u4E58\n            #ifdef LIGHT2D_SCENEMODE_ADD\n                color.rgb = min(vec3(1.0), color.rgb + texture2D(u_LightAndShadow2D_AddMode, uv).rgb * side); //\u573A\u666F\u548C\u706F\u5149\u76F8\u52A0\u6A21\u5F0F\n            #endif\n            #ifdef LIGHT2D_SCENEMODE_SUB\n                color.rgb = max(vec3(0.0), color.rgb - texture2D(u_LightAndShadow2D_SubMode, uv).rgb * side); //\u573A\u666F\u548C\u706F\u5149\u76F8\u51CF\u6A21\u5F0F\n            #endif\n            #ifdef LIGHT2D_NORMAL_PARAM\n                vec3 dr = normalize(u_LightDirection);\n                vec3 normal = normalize(texture2D(u_normal2DTexture, v_texcoord).rgb * 2.0 - 1.0);\n                color.rgb = color.rgb * ((1.0 - u_normal2DStrength) + abs(dot(dr, normal.rgb)) * u_normal2DStrength);\n            #endif\n            color.rgb = min(vec3(1.0), color.rgb + ambient); //\u53E0\u52A0\u73AF\u5883\u5149\n        #endif\n    }\n#endif\n\n    void setglColor(in vec4 color){\n        color.a *= v_color.w;\n        vec4 transColor = v_color;\n        #ifndef GAMMASPACE\n            transColor = gammaToLinear(v_color);\n        #endif\n        color.rgb *= transColor.rgb;\n        gl_FragColor = color;\n    }\n\n    vec2 transformUV(in vec2 texcoord, in vec4 tilingOffset)\n    {\n        vec2 uv = texcoord * tilingOffset.zw + tilingOffset.xy;\n        return uv;\n    }\n\n#endif\n\n';

  // src/layaAir/laya/webgl/shader/d2/NewShader/ClipFrag.glsl
  var ClipFrag_default = "#if !defined(ClipFrag_lib)\n    #define ClipFrag_lib\n\nvarying vec2 v_cliped;\n\nvoid clip(){\n    #ifdef UNIFORMCLIP\n        if(v_cliped.x<0.) discard;\n        if(v_cliped.x>1.) discard;\n        if(v_cliped.y<0.) discard;\n        if(v_cliped.y>1.) discard;\n    #endif\n    // if(v_cliped.x<0.) gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);\n    // if(v_cliped.x>1.) gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);\n    // if(v_cliped.y<0.) gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);\n    // if(v_cliped.y>1.) gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);\n}\n\n#endif  //ClipFrag_lib";

  // src/layaAir/laya/webgl/shader/d2/NewShader/ClipVertex.glsl
  var ClipVertex_default = "#if !defined(ClipVertex_lib)\n    #define ClipVertex_lib\n\n#ifdef MATERIALCLIP\n    uniform vec4 u_mClipMatDir;\n    uniform vec4 u_mClipMatPos;\n#endif\n\nvarying vec2 v_cliped;\n\n#ifdef UNIFORMCLIP\n    uniform vec4 u_clipMatDir;\n    uniform vec4 u_clipMatPos;// \u8FD9\u4E2A\u662F\u5168\u5C40\u7684\uFF0C\u4E0D\u7528\u518D\u5E94\u7528\u77E9\u9635\u4E86\u3002\n#endif\n\nvoid clip(inout vec2 globalPos){\n    \n#ifdef UNIFORMCLIP\n    // \u6839\u636E\u89C6\u53E3\u8C03\u6574\u4F4D\u7F6E\n    vec4 clipMatDir;\n    vec4 clipMatPos;\n    #ifdef MATERIALCLIP\n        clipMatDir = u_mClipMatDir;\n        clipMatPos = u_mClipMatPos;\n\n        float tx = clipMatPos.z;\n        float ty = clipMatPos.w;\n        float cmaxx = tx + clipMatDir.x;\n        float cmaxy = ty + clipMatDir.w;\n        //\u8BA1\u7B97\u4EA4\u96C6\n        float parentMinX = u_clipMatPos.x;\n        float parentMinY = u_clipMatPos.y;\n        float offsetx = u_clipMatPos.z - parentMinX;\n        float offsety = u_clipMatPos.w - parentMinY;\n        float parentMaxX = parentMinX + u_clipMatDir.x;\n        float parentMaxY = parentMinY + u_clipMatDir.w;\n\n        if (tx < parentMinX) {\n            clipMatDir.x -= (parentMinX - tx);\n            tx = clipMatPos.x = parentMinX;\n        }\n\n        if (cmaxx > parentMaxX) {\n            clipMatDir.x -= (cmaxx - parentMaxX);\n        }\n\n        if (ty < parentMinY) {\n            clipMatDir.w -= (parentMinY - ty);\n            ty = clipMatPos.y = parentMinY;\n            // offsety += parentMinY - cm.ty;\n        }\n        \n        if (cmaxy > parentMaxY) {\n            clipMatDir.w -= (cmaxy - parentMaxY);\n        }\n\n        clipMatPos.zw = vec2(tx + offsetx,ty + offsety);\n    #else\n        clipMatDir = u_clipMatDir;\n        clipMatPos = u_clipMatPos;\n    #endif\n\n    vec2 cliped;\n    float clipw = length(clipMatDir.xy);\n    float cliph = length(clipMatDir.zw);\n    vec2 clippos = globalPos - clipMatPos.xy;	//pos\u5DF2\u7ECF\u5E94\u7528\u77E9\u9635\u4E86\uFF0C\u4E3A\u4E86\u51CF\u7684\u6709\u610F\u4E49\uFF0Cclip\u7684\u4F4D\u7F6E\u4E5F\u8981\u7F29\u653E\n    if(clipw>20000. && cliph>20000.)\n        cliped = vec2(0.5,0.5);\n    else {\n        //clipdir\u662F\u5E26\u7F29\u653E\u7684\u65B9\u5411\uFF0C\u7531\u4E8E\u4E0A\u9762clippos\u662F\u5728\u7F29\u653E\u540E\u7684\u7A7A\u95F4\u8BA1\u7B97\u7684\uFF0C\u6240\u4EE5\u9700\u8981\u628A\u65B9\u5411\u5148normalize\u4E00\u4E0B\n        cliped =vec2( dot(clippos,clipMatDir.xy)/clipw/clipw, dot(clippos,clipMatDir.zw)/cliph/cliph);\n    }\n    \n    globalPos = clippos + clipMatPos.zw;\n    v_cliped = cliped;\n#endif\n}\n\n#endif  //ClipVertex_lib";

  // src/layaAir/laya/webgl/shader/d2/NewShader/Sprite2DVertex.glsl
  var Sprite2DVertex_default = '\n#include "ClipVertex.glsl";\n#include "Color.glsl";\n\n#ifdef CAMERA2D\n uniform mat3 u_view2D;\n#endif\n\n#ifdef SPRITE2DGLOBAL\n#endif // SPRITE2DGLOBAL\n\n#ifdef RENDERTEXTURE\n    uniform vec3 u_InvertMat_0;\n    uniform vec3 u_InvertMat_1;\n#endif\n\n#ifdef VERTEX_SIZE\n    uniform vec4 u_vertexSize;\n#endif\n\nuniform vec3 u_NMatrix_0;\nuniform vec3 u_NMatrix_1;\n\nuniform vec2 u_size;\n\nvarying vec4 v_color;\n\nvoid transfrom(vec2 pos,vec3 xDir,vec3 yDir,out vec2 outPos){\n    outPos.x=xDir.x*pos.x+xDir.y*pos.y +xDir.z;\n    outPos.y=yDir.x*pos.x+yDir.y*pos.y +yDir.z;\n}\n\nvoid getGlobalPos(in vec2 localPos,out vec2 globalPos){\n    transfrom(localPos,u_NMatrix_0,u_NMatrix_1,globalPos);\n}\n\nvoid getProjectPos(in vec2 viewPos,out vec4 projectPos){\n    projectPos= vec4((viewPos.x/u_size.x-0.5)*2.0,(0.5-viewPos.y/u_size.y)*2.0,0.,1.0);\n    #ifdef INVERTY\n        projectPos.y = -projectPos.y;\n    #endif\n}\n\nvoid getViewPos(in vec2 globalPos,out vec2 viewPos){\n    #ifdef RENDERTEXTURE\n        vec2 tempPos;\n        transfrom(globalPos , u_InvertMat_0, u_InvertMat_1, tempPos);\n        // tempPos -= u_clipMatPos.xy - u_clipMatPos.zw;\n        // tempPos.x += (u_clipMatPos.x - u_clipMatPos.z); \n        // tempPos.y += (u_clipMatPos.y - u_clipMatPos.w);\n\n        #ifdef CAMERA2D\n            viewPos.xy = (u_view2D *vec3(tempPos,1.0)).xy+u_size/2.;\n        #else\n            viewPos.xy = tempPos;\n        #endif\n    #else\n        #ifdef CAMERA2D\n            viewPos.xy = (u_view2D *vec3(globalPos,1.0)).xy+u_size/2.;\n        #else\n            viewPos.xy = globalPos;\n        #endif\n    #endif\n}\n\n#ifdef TEXTUREVS\n    \n    struct vertexInfo {\n        vec2 pos;\n        vec4 color;\n        vec2 cliped;\n        vec4 texcoordAlpha;\n        float useTex;\n        float useClip;\n        vec4 customs;\n    };\n\n    uniform float u_VertAlpha;\n	//texture\u548Cfillrect\u4F7F\u7528\u7684\u3002\n    // attribute vec4 a_posuv;\n    // attribute vec4 a_attribColor;\n    // attribute vec4 a_attribFlags;\n\n    varying vec4 v_texcoordAlpha;\n    varying float v_useTex;\n    varying float v_useClip;\n    varying vec4 v_customs;\n\n    #ifdef USE_TEX_ARRAY\n        varying float v_texLayer;\n    #endif\n\n    void getVertexInfo(inout vertexInfo info){\n       	//texcoordAlpha\n        info.texcoordAlpha.xy = a_posuv.zw;\n        //color\n        info.color = a_attribColor;\n\n        #ifdef VERTEXALPHA\n            info.color.a*=a_attribFlags.z;\n        #else\n            info.color.a*=u_VertAlpha;\n        #endif\n\n	    info.color.xyz*= info.color.a;//\u53CD\u6B63\u540E\u9762\u4E5F\u8981\u9884\u4E58\n        //useTex\n        info.useTex = a_attribFlags.r;\n        //useClip\n        info.useClip = a_attribFlags.g;\n        //customs\n        info.customs = a_customs;\n\n        vec2 pos;\n        #ifdef VERTEX_SIZE\n            pos = (a_posuv.xy*u_vertexSize.zw ) +u_vertexSize.xy;//xy\u504F\u79FB\uFF0Czw \u9876\u70B9\u6269\u5C55\u5BBD\u9AD8\n        #else\n            pos = a_posuv.xy;\n        #endif\n        info.pos = pos;\n    }\n\n    vec4 getPosition(in vec2 positionOS){\n        vec2 globalPos;\n        #ifdef VERTEX_SIZE\n            getGlobalPos(positionOS , globalPos);\n        #else\n            globalPos = positionOS;\n        #endif\n       \n        clip(globalPos);\n\n        vec2 viewPos;\n        getViewPos(globalPos,viewPos);\n        vec4 pos;\n        getProjectPos(viewPos,pos);\n        return pos;\n    }\n\n#endif\n\n#ifdef BASERENDER2D\n    varying vec2 v_texcoord;\n\n    uniform vec4 u_baseRenderColor;\n    #ifdef UNITQUAD\n        uniform vec2 u_baseRenderSize2D;\n    #endif\n\n    struct vertexInfo {\n        vec4 color;\n        vec2 uv;\n        vec2 pos;\n        vec2 lightUV;\n    };\n\n    #ifdef LIGHT2D_ENABLE\n        varying vec2 v_lightUV; //\u5149\u5F71\u56FE\u91C7\u6837\u5750\u6807\n        uniform vec4 u_LightAndShadow2DParam; //\u5149\u5F71\u56FE\u5C3A\u5BF8\u548C\u4F4D\u7F6E\n        // uniform vec3 u_LightAndShadow2DSceneInv0; //scene\u9006\u77E9\u9635\n        // uniform vec3 u_LightAndShadow2DSceneInv1;\n        // uniform vec3 u_LightAndShadow2DStageMat0; //stage\u77E9\u9635\n        // uniform vec3 u_LightAndShadow2DStageMat1;\n\n        void lightAndShadow(vertexInfo info) {\n            v_lightUV = info.lightUV;\n        }\n\n        void invertMat(inout vec3 v1, inout vec3 v2) {\n            float a1 = v1.x;\n            float b1 = v2.x;\n            float c1 = v1.y;\n            float d1 = v2.y;\n            float tx1 = v1.z;\n            float ty1 = v2.z;\n            float n = a1 * d1 - b1 * c1;\n            v1.x = d1 / n;\n            v2.x = -b1 / n;\n            v1.y = -c1 / n;\n            v2.y = a1 / n;\n            v1.z = (c1 * ty1 - d1 * tx1) / n;\n            v2.z = -(a1 * ty1 - b1 * tx1) / n;\n        }\n    #endif\n\n    void getVertexInfo(inout vertexInfo info){\n        #ifdef UNITQUAD\n            info.pos = a_position.xy * u_baseRenderSize2D;\n        #else\n            info.pos = a_position.xy;\n        #endif\n        info.color = vec4(1.0,1.0,1.0,1.0);\n        #ifdef COLOR\n            info.color = a_color;\n            info.color.rgb *=a_color.a;\n        #endif\n\n        vec4 ucolor = linearToGamma(u_baseRenderColor);\n        ucolor.rgb *= ucolor.a;\n        info.color*= ucolor;\n        #ifdef UV\n            info.uv = a_uv;\n        #endif\n\n        #ifdef LIGHT2D_ENABLE\n            vec2 global;\n            // vec3 stageInv0 = vec3(u_LightAndShadow2DStageMat0.x, u_LightAndShadow2DStageMat0.y, u_LightAndShadow2DStageMat0.z);\n            // vec3 stageInv1 = vec3(u_LightAndShadow2DStageMat1.x, u_LightAndShadow2DStageMat1.y, u_LightAndShadow2DStageMat1.z);\n            // invertMat(stageInv0, stageInv1); //\u83B7\u53D6stage\u7684\u9006\u77E9\u9635\n            getGlobalPos(info.pos, global); //\u5148\u83B7\u5F97\u5B8C\u6574\u4E16\u754C\u53D8\u6362\u7684\u4F4D\u7F6E\n            // transfrom(global, stageInv0, stageInv1, global); //\u5148\u53BB\u9664stage\u53D8\u6362\n            // transfrom(global, u_LightAndShadow2DSceneInv0, u_LightAndShadow2DSceneInv1, global); //\u518D\u53BB\u9664scene\u53D8\u6362\n            // transfrom(global, u_LightAndShadow2DStageMat0, u_LightAndShadow2DStageMat1, global); //\u518D\u6062\u590Dstage\u53D8\u6362\n            //\u73B0\u5728global\u4E2D\u7684\u503C\u5C31\u548C\u751F\u6210\u5149\u5F71\u56FE\u65F6\u7684\u503C\u4E00\u81F4\u4E86\uFF0C\u57FA\u4E8E\u8FD9\u4E2A\u503C\u751F\u6210\u5149\u5F71\u56FE\u91C7\u6837uv\u5750\u6807\n            info.lightUV.x = (global.x - u_LightAndShadow2DParam.x) / u_LightAndShadow2DParam.z;\n            info.lightUV.y = 1.0 - (global.y - u_LightAndShadow2DParam.y) / u_LightAndShadow2DParam.w;\n        #endif\n    }\n    \n    vec4 getPosition(in vec2 positionOS){\n        vec2 globalPos;\n        getGlobalPos(positionOS,globalPos);\n\n        clip(globalPos);\n\n        vec2 viewPos;\n        getViewPos(globalPos,viewPos);\n        vec4 pos;\n        getProjectPos(viewPos,pos);\n        return pos;\n    }\n#endif\n';

  // src/layaAir/laya/webgl/shader/d2/files/OutputTransform.glsl
  var OutputTransform_default = "#if !defined(OutputTransform_lib)\n    #define OutputTransform_lib\n\nvec3 gammaCorrect(in vec3 color, float gammaValue)\n{\n    return pow(color, vec3(gammaValue));\n}\n\nvec4 gammaCorrect(in vec4 color)\n{\n    // todo color gamut gamma value\n    // default sRGB\n    float gammaValue = 1.0 / 2.2;\n    return vec4(gammaCorrect(color.rgb, gammaValue), color.a);\n}\n\n#ifdef BRIDGE3D_CLIP\n    uniform vec4 u_Bridge3DClipDir;   // RT pixel space clip direction (dirX.x, dirX.y, dirY.x, dirY.y)\n    uniform vec4 u_Bridge3DClipPos;   // RT pixel space clip position (originX, originY, rtH, -)\n#endif\n\nvec4 outputTransform(in vec4 color)\n{\n    #ifdef BRIDGE3D_CLIP\n        vec2 fragPos = vec2(gl_FragCoord.x, u_Bridge3DClipPos.z - gl_FragCoord.y);\n        vec2 clppos = fragPos - u_Bridge3DClipPos.xy;\n        float clipw = length(u_Bridge3DClipDir.xy);\n        float cliph = length(u_Bridge3DClipDir.zw);\n        if (clipw > 20000.0 && cliph > 20000.0) {\n            // default clip (very large), no clipping\n        } else {\n            float cx = dot(clppos, u_Bridge3DClipDir.xy) / clipw / clipw;\n            float cy = dot(clppos, u_Bridge3DClipDir.zw) / cliph / cliph;\n            if (cx < 0.0 || cx > 1.0 || cy < 0.0 || cy > 1.0) discard;\n        }\n    #endif\n\n    #ifdef GAMMACORRECT\n    // render in linear, output gamma\n    return gammaCorrect(color);\n    #else // GAMMACORRECT\n    return color;\n    #endif // GAMMACORRECT\n}\n\n#endif // OutputTransform_lib\n";

