  // src/layaAir/laya/d3/shader/pbr/BRDF.glsl
  var BRDF_default = '#if !defined(BRDF)\n    #define BRDF\n\n// Specular implementations\nfloat D_GGX(float roughness, float NoH, vec3 h, vec3 n)\n{\n    // todo \u7CBE\u5EA6\n    #if !defined(GL_FRAGMENT_PRECISION_HIGH)\n    vec3 NxH = cross(n, h);\n    float oneMinusNoHSquared = dot(NxH, NxH);\n    #else\n    float oneMinusNoHSquared = 1.0 - NoH * NoH;\n    #endif\n\n    float a = NoH * roughness;\n    float k = roughness / (oneMinusNoHSquared + a * a);\n    float d = k * k * INVERT_PI;\n\n    return saturateMediump(d);\n}\n\nfloat D_GGX_Anisotropic(float NoH, const vec3 h, const vec3 t, const vec3 b, float at, float ab)\n{\n    float ToH = dot(t, h);\n    float BoH = dot(b, h);\n    float a2 = at * ab;\n    highp vec3 v = vec3(ab * ToH, at * BoH, a2 * NoH);\n    highp float v2 = dot(v, v);\n    float w2 = a2 / v2;\n    return a2 * w2 * w2 * INVERT_PI;\n}\n\nfloat D_Charlie(float roughness, float NoH)\n{\n    float invR = 1.0 / roughness;\n    float cos2h = NoH * NoH;\n    float sin2h = max(1.0 - cos2h, 0.0078125);\n    return (2.0 + invR) * pow(sin2h, invR * 0.5) * 0.5 * INVERT_PI;\n}\n\nfloat V_SmithGGXCorrelated(float roughness, float NoV, float NoL)\n{\n    float a2 = roughness * roughness;\n    float lambdaV = NoL * sqrt((NoV - a2 * NoV) * NoV + a2);\n    float lambdaL = NoV * sqrt((NoL - a2 * NoL) * NoL + a2);\n    float v = 0.5 / (lambdaV + lambdaL);\n\n    return saturateMediump(v);\n}\n\nfloat V_SmithGGXCorrelated_Fast(float roughness, float NoV, float NoL)\n{\n    float v = 0.5 / mix(2.0 * NoL * NoV, NoL + NoV, roughness);\n    return saturateMediump(v);\n}\n\n// Kelemen 2001, "A Microfacet Based Coupled Specular-Matte BRDF Model with Importance Sampling"\nfloat V_kelemen(float LoH)\n{\n    return saturateMediump(0.25 / (LoH * LoH));\n}\n\nfloat lCharlieNumericHelper(float x, float alphaG)\n{\n    float oneMinusAlphaSq = (1.0 - alphaG) * (1.0 - alphaG);\n    float a = mix(21.5473, 25.3245, oneMinusAlphaSq);\n    float b = mix(3.82987, 3.32435, oneMinusAlphaSq);\n    float c = mix(0.19823, 0.16801, oneMinusAlphaSq);\n    float d = mix(-1.97760, -1.27393, oneMinusAlphaSq);\n    float e = mix(-4.32054, -4.85967, oneMinusAlphaSq);\n    return a / (1.0 + b * pow(x, c)) + d * x + e;\n}\n\nfloat lCharlie(float cosTheta, float alphaG)\n{\n    if (abs(cosTheta) < 0.5)\n	{\n	    return exp(lCharlieNumericHelper(cosTheta, alphaG));\n	}\n    else\n	{\n	    return exp(2.0 * lCharlieNumericHelper(0.5, alphaG) - lCharlieNumericHelper(1.0 - cosTheta, alphaG));\n	}\n}\n\nfloat V_Charlie(float NoL, float NoV, float roughness)\n{\n    float alphaG = roughness * roughness;\n    return clamp(1.0 / ((1.0 + lCharlie(NoV, alphaG) + lCharlie(NoL, alphaG)) * (4.0 * NoV * NoL)), 0.0, 1.0);\n}\n\n// Neubelt and Pettineo 2013, "Crafting a Next-gen Material Pipeline for The Order: 1886"\nfloat V_Neubelt(float NoV, float NoL)\n{\n    return saturateMediump(1.0 / (4.0 * (NoL + NoV - NoL * NoV)));\n}\n\nfloat V_SmithGGXCorrelated_Anisotropic(float at, float ab, float ToV, float BoV, float ToL, float BoL, float NoV, float NoL)\n{\n    float lambdaV = NoL * length(vec3(at * ToV, ab * BoV, NoV));\n    float lambdaL = NoV * length(vec3(at * ToL, ab * BoL, NoL));\n    float v = 0.5 / (lambdaV + lambdaL);\n    return saturateMediump(v);\n}\n\nvec3 F_Schlick(vec3 f0, float f90, float VoH)\n{\n    return f0 + (f90 - f0) * pow5(1.0 - VoH);\n}\n\nvec3 F_Schlick(vec3 f0, float VoH)\n{\n    return f0 + (1.0 - f0) * pow5(1.0 - VoH);\n}\n\nfloat F_Schlick(float f0, float f90, float VoH)\n{\n    return f0 + (f90 - f0) * pow5(1.0 - VoH);\n}\n\nfloat F_Schlick(float f0, float VoH)\n{\n    return f0 + (1.0 - f0) * pow5(1.0 - VoH);\n}\n\nvec3 F_Schlick(vec3 f0, vec3 f90, float VoH)\n{\n    return f0 + (f90 - f0) * pow5(1.0 - VoH);\n}\n\n    #ifdef IRIDESCENCE\n\n// CIE XYZ to REC.709\nconst mat3 XYZ_to_REC709_MAT = mat3(\n    vec3(3.2409699419, -0.9692436363, 0.0556300797),\n    vec3(-1.5373831776, 1.8759675015, -0.2039769589),\n    vec3(-0.498610760, 0.0415550574, 1.0569715142));\n\nfloat IorToFresnel0(float iorT, float iorI)\n{\n    return pow2((iorT - iorI) / (iorT + iorI));\n}\n\nvec3 IorToFresnel0(vec3 iorT, float iorI)\n{\n    return pow2((iorT - vec3(iorI)) / (iorT + vec3(iorI)));\n}\n\n// air to surfaceR0 ior\nvec3 Fresnel0ToIor(vec3 f0)\n{\n    vec3 sqrtF0 = sqrt(f0);\n    return (1.0 + sqrtF0) / (1.0 - sqrtF0);\n}\n\nvec3 evalSensitivity(float OPD, vec3 shift)\n{\n    float phase = 2.0 * PI * OPD * 1.0e-9;\n    vec3 val = vec3(5.4856e-13, 4.4201e-13, 5.2481e-13);\n    vec3 pos = vec3(1.6810e+06, 1.7953e+06, 2.2084e+06);\n    vec3 var = vec3(4.3278e+09, 9.3046e+09, 6.6121e+09);\n    vec3 xyz = val * sqrt(2.0 * PI * var) * cos(pos * phase + shift) * exp(-pow2(phase) * var);\n    xyz.x += 9.7470e-14 * sqrt(2.0 * PI * 4.5282e+09) * cos(2.2399e+06 * phase + shift[0]) * exp(-4.5282e+09 * pow2(phase));\n    xyz /= 1.0685e-7;\n    vec3 srgb = XYZ_to_REC709_MAT * xyz;\n    return srgb;\n}\n\n// https://belcour.github.io/blog/research/publication/2017/05/01/brdf-thin-film.html\nvec3 evalIridescence(float outsideIOR, float eta2, float cosTheta1, float thinFilmThickness, vec3 baseF0)\n{\n    vec3 I;\n    float iridescenceIor = mix(outsideIOR, eta2, smoothstep(0.0, 0.03, thinFilmThickness));\n\n    float sinTheta2Sq = pow2(outsideIOR / iridescenceIor) * (1.0 - pow2(cosTheta1));\n\n    float cosTheta2Sq = 1.0 - sinTheta2Sq;\n    if (cosTheta2Sq < 0.0)\n	{\n	    return vec3(1.0);\n	}\n    float cosTheta2 = sqrt(cosTheta2Sq);\n\n    float R0 = IorToFresnel0(iridescenceIor, outsideIOR);\n    float R12 = F_Schlick(R0, cosTheta1);\n    float R21 = R12;\n    float T121 = 1.0 - R12;\n    float phi12 = 0.0;\n    if (iridescenceIor < outsideIOR)\n	phi12 = PI;\n    float phi21 = PI - phi12;\n\n    vec3 baseIOR = Fresnel0ToIor(clamp(baseF0, 0.0, 0.9999));\n\n    vec3 R1 = IorToFresnel0(baseIOR, iridescenceIor);\n    vec3 R23 = F_Schlick(R1, cosTheta2);\n    vec3 phi23 = vec3(0.0);\n\n    if (baseIOR[0] < iridescenceIor)\n	phi23[0] = PI;\n    if (baseIOR[1] < iridescenceIor)\n	phi23[1] = PI;\n    if (baseIOR[2] < iridescenceIor)\n	phi23[2] = PI;\n\n    float OPD = 2.0 * iridescenceIor * thinFilmThickness * cosTheta2;\n    vec3 phi = vec3(phi21) + phi23;\n\n    vec3 R123 = clamp(R12 * R23, 1e-5, 0.9999);\n    vec3 r123 = sqrt(R123);\n    vec3 Rs = pow2(T121) * R23 / (vec3(1.0) - R123);\n\n    vec3 C0 = R12 + Rs;\n    I = C0;\n\n    vec3 Cm = Rs - T121;\n    for (int m = 1; m <= 2; ++m)\n	{\n	    Cm *= r123;\n	    vec3 Sm = 2.0 * evalSensitivity(float(m) * OPD, float(m) * phi);\n	    I += Cm * Sm;\n	}\n\n    return max(I, vec3(0.0));\n}\n    #endif // IRIDESCENCE\n\n// Specular dispatch\n\n// D\nfloat distribution(float roughness, float NoH, vec3 h, vec3 n)\n{\n    return D_GGX(roughness, NoH, h, n);\n}\n\n// V\nfloat visibility(float roughness, float NoV, float NoL)\n{\n    return V_SmithGGXCorrelated(roughness, NoV, NoL);\n}\n\n// F\nvec3 fresnel(vec3 f0, float LoH)\n{\n    float f90 = saturate(dot(f0, vec3(50.0 * 0.33)));\n    return F_Schlick(f0, f90, LoH);\n\n    // return F_Schlick(f0, LoH);\n}\n\nvec3 fresnel(vec3 f0, vec3 f90, float LoH)\n{\n    return F_Schlick(f0, f90, LoH);\n}\n\n// diffuse BRDF implementations\n\nfloat Fd_Lambert()\n{\n    // https://seblagarde.wordpress.com/2012/01/08/pi-or-not-to-pi-in-game-lighting-equation/\n    // return INVERT_PI;\n    return 1.0;\n}\n\nfloat Fd_Burley(float roughness, float NoV, float NoL, float LoH)\n{\n    float f90 = 0.5 + 2.0 * roughness * LoH * LoH;\n    float lightScatter = F_Schlick(1.0, f90, NoL);\n    float veiwScatter = F_Schlick(1.0, f90, NoV);\n    return lightScatter * veiwScatter * INVERT_PI;\n}\n\n    #ifdef IRIDESCENCE\nvec3 Fd_IridescenceLambert(vec3 f0, vec3 f90, vec3 iridescenceFresnel, float iridescenceFactor, float VoH)\n{\n    vec3 iridescenceFresnelMax = vec3(vecmax(iridescenceFresnel));\n    vec3 schlickFresnel = F_Schlick(f0, f90, VoH);\n\n    vec3 F = mix(schlickFresnel, iridescenceFresnelMax, iridescenceFactor);\n\n    return (1.0 - F) * Fd_Lambert();\n}\n    #endif // IRIDESCENCE\n\n#endif // BRDF';

  // src/layaAir/laya/d3/shader/pbr/pbrGI.glsl
  var pbrGI_default = '#if !defined(pbrGI_lib)\n    #define pbrGI_lib\n\n    #include "globalIllumination.glsl";\n\n    #ifdef ANISOTROPIC\nvec3 anisotropyBentNormal(const in Surface surface, const in PixelInfo info)\n{\n    float anisotropy = surface.anisotropy;\n    vec3 anisotropyDirection = info.anisotropicB;\n\n    vec3 n = info.normalWS;\n    vec3 v = info.viewDir;\n\n    // float tangentRoughness = mix(roughness, 1.0, anisotropy * anisotropy);\n    float roughness = surface.perceptualRoughness;\n    vec3 anisotropicTangent = cross(anisotropyDirection, v);\n    vec3 anisotropicNormal = cross(anisotropicTangent, anisotropyDirection);\n    float bendFactor = 1.0 - anisotropy * (1.0 - roughness);\n    float bendFactorPow4 = pow2(bendFactor) * pow2(bendFactor);\n    vec3 bentNormal = normalize(mix(anisotropicNormal, n, bendFactorPow4));\n\n    return bentNormal;\n}\n    #endif // ANISOTROPIC\n\n// \u83B7\u53D6\u53CD\u5C04\u5411\u91CF\nvec3 getReflectedVector(const in vec3 n, const in vec3 v, const in vec3 positionWS)\n{\n    vec3 r;\n    r = reflect(-v, n);\n\n    #ifdef SPECCUBE_BOX_PROJECTION\n    r = getBoxProjectionReflectedVector(r, positionWS);\n    #endif // SPECCUBE_BOX_PROJECTION\n\n    return r;\n}\n\n    #ifdef IRIDESCENCE\nvoid iridescenceIBL(const in Surface surface, const in PixelInfo info, in vec3 E, inout vec3 Fd, inout vec3 Fr)\n{\n    vec3 dfg = info.dfg;\n    float NoV = info.NoV;\n    vec3 n = info.normalWS;\n    vec3 v = info.viewDir;\n    vec3 positionWS = info.positionWS;\n    vec3 iridescenceFresnel = info.iridescenceFresnel;\n\n    vec3 diffuseColor = surface.diffuseColor;\n    float roughness = surface.perceptualRoughness;\n    float occlusion = surface.occlusion;\n    float iridescenceFactor = surface.iridescence;\n\n    // diffuse\n    vec3 irradiance = diffuseIrradiance(n, positionWS, info.viewDir);\n    Fd += diffuseColor * irradiance * (1.0 - E) * occlusion;\n\n    // specular\n    vec3 iridescenceF0 = mix(surface.f0, iridescenceFresnel, vec3(iridescenceFactor));\n    vec3 Er = mix(dfg.xxx, dfg.yyy, iridescenceF0);\n\n	#ifdef ANISOTROPIC\n    vec3 bentNormal = anisotropyBentNormal(surface, info);\n    vec3 r = getReflectedVector(bentNormal, v, positionWS);\n	#else // ANISOTROPIC\n    vec3 r = getReflectedVector(n, v, positionWS);\n	#endif // ANISOTROPIC\n\n    vec3 indirectSpecular = specularRadiance(r, roughness);\n    Fr += Er * indirectSpecular * occlusion * (1.0 + Er * (1.0 / dfg.y - 1.0));\n}\n    #endif // IRIDESCENCE\n\n    #ifdef SHEEN\nvoid sheenIBL(const in Surface surface, const in PixelInfo info, inout vec3 Fd, inout vec3 Fr)\n{\n    vec3 v = info.viewDir;\n    vec3 n = info.normalWS;\n    vec3 positionWS = info.positionWS;\n\n    float occlusion = surface.occlusion;\n    float roughness = surface.sheenPerceptualRoughness;\n\n    Fd *= info.sheenScaling;\n    Fr *= info.sheenScaling;\n\n    vec3 r = getReflectedVector(n, v, positionWS);\n    vec3 indirectSpecular = specularRadiance(r, roughness);\n\n    Fr += indirectSpecular * info.sheenDfg * surface.sheenColor * occlusion;\n}\n    #endif // SHEEN\n\n    #ifdef CLEARCOAT\nvoid clearCoatIBL(const in Surface surface, const in PixelInfo info, inout vec3 Fd, inout vec3 Fr)\n{\n    vec3 v = info.viewDir;\n    vec3 n = info.clearCoatNormal;\n    float NoV = info.clearCoatNoV;\n    vec3 positionWS = info.positionWS;\n\n    float clearCoat = surface.clearCoat;\n    float roughness = surface.clearCoatPerceptualRoughness;\n    float occlusion = surface.occlusion;\n\n    float Fc = F_Schlick(0.04, 1.0, NoV) * clearCoat;\n    float attenuation = 1.0 - Fc;\n    Fd *= attenuation;\n    Fr *= attenuation;\n\n    vec3 r = getReflectedVector(n, v, positionWS);\n    vec3 indirectSpecular = specularRadiance(r, roughness);\n\n    Fr += indirectSpecular * Fc * occlusion;\n}\n    #endif // CLEARCOAT\n\n    #ifdef TRANSMISSION\nvec3 getRefraction(const in Surface surface, const in PixelInfo info)\n{\n    vec3 position = info.positionWS;\n\n	#ifdef THICKNESS\n\n    vec3 n = info.normalWS;\n    vec3 r = -info.viewDir;\n    float airIOR = 1.0;\n    float etaIR = airIOR / surface.ior;\n\n    vec3 refractionV = normalize(refract(r, n, etaIR)) * surface.thickness * info.worldScale.xyz;\n\n    position += refractionV;\n\n	#endif // THICKNESS\n\n    vec4 p = u_ViewProjection * vec4(position, 1.0);\n    vec2 refractionUV = (p.xy / p.w) * 0.5 + 0.5;\n\n    float refractionLOD = u_OpaqueTextureParams.z * surface.perceptualRoughness * saturate(surface.ior * 2.0 - 2.0);\n    vec3 refraction = texture2DLodEXT(u_CameraOpaqueTexture, refractionUV, refractionLOD).xyz;\n\n    return refraction;\n}\n\nvec3 transmissionIBL(const in Surface surface, const in PixelInfo info, in vec3 E)\n{\n    // refraction\n    vec3 refraction = getRefraction(surface, info);\n\n	#ifndef THICKNESS\n    E *= 1.0 + surface.transmission * (1.0 - E.g) / (1.0 + E.g);\n	#endif // THICKNESS\n\n	#ifdef THICKNESS\n\n    // ABSORPTION\n    vec3 attenuationColor = surface.attenuationColor;\n    float attenuationDistance = surface.attenuationDistance;\n    vec3 absorption = -log(attenuationColor) / (attenuationDistance);\n    vec3 T = exp(-absorption * info.worldScale.xyz * surface.thickness);\n\n	#endif // THICKNESS\n\n    vec3 Ft = refraction;\n\n    Ft *= surface.diffuseColor;\n\n    Ft *= 1.0 - E;\n\n	#ifdef THICKNESS\n    Ft *= T;\n	#endif // THICKNESS\n\n    return Ft * surface.transmission;\n}\n\n    #endif // TRANSMISSION\n\nvoid baseIBL(const in Surface surface, const in PixelInfo info, in vec3 E, inout vec3 Fd, inout vec3 Fr)\n{\n    vec3 dfg = info.dfg;\n    float NoV = info.NoV;\n    vec3 n = info.normalWS;\n    vec3 v = info.viewDir;\n    vec3 positionWS = info.positionWS;\n\n    vec3 diffuseColor = surface.diffuseColor;\n    float roughness = surface.perceptualRoughness;\n    float occlusion = surface.occlusion;\n\n    #ifdef ANISOTROPIC\n    vec3 bentNormal = anisotropyBentNormal(surface, info);\n    vec3 r = getReflectedVector(bentNormal, v, positionWS);\n    #else // ANISOTROPIC\n    vec3 r = getReflectedVector(n, v, positionWS);\n    #endif // ANISOTROPIC\n\n    vec3 indirectSpecular = specularRadiance(r, roughness);\n\n    // todo\n    float specularAO = occlusion;\n    Fr += E * indirectSpecular * specularAO * info.energyCompensation;\n\n    #if defined(USELIGHTMAP)\n\n    vec2 lightmapUV = info.lightmapUV;\n    vec3 bakedlight = getBakedLightmapColor(lightmapUV, n);\n    Fd += bakedlight * diffuseColor;\n\n    #else // USELIGHTMAP\n\n    vec3 irradiance = diffuseIrradiance(n, positionWS, info.viewDir);\n    Fd += diffuseColor * irradiance * (1.0 - E) * occlusion;\n\n    #endif // USELIGHTMAP\n}\n\nvec3 getE(const in Surface surface, const in PixelInfo info)\n{\n    #ifdef IRIDESCENCE\n\n    vec3 dfg = info.dfg;\n    float NoV = info.NoV;\n    vec3 iridescenceFresnel = info.iridescenceFresnel;\n    vec3 f0 = surface.f0;\n    float iridescenceFactor = surface.iridescence;\n    vec3 iridescenceFresnelMax = vec3(vecmax(iridescenceFresnel));\n    vec3 schlickFresnel = F_Schlick(f0, vec3(1.0), NoV);\n    vec3 F = mix(schlickFresnel, iridescenceFresnelMax, iridescenceFactor);\n    vec3 E = mix(dfg.xxx, dfg.yyy, F);\n\n    #else // IRIDESCENCE\n\n    vec3 dfg = info.dfg;\n    vec3 f0 = surface.f0;\n    vec3 f90 = surface.f90;\n    // vec3 E = mix(dfg.xxx, dfg.yyy, f0);\n    vec3 E = (f90 - f0) * dfg.x + f0 * dfg.y;\n\n    #endif // IRIDESCENCE\n    return E;\n}\n\nvec3 PBRGI(const in Surface surface, const in PixelInfo info)\n{\n    vec3 Fd = vec3(0.0);\n    vec3 Fr = vec3(0.0);\n\n    vec3 E = getE(surface, info);\n\n    #ifdef IRIDESCENCE\n    iridescenceIBL(surface, info, E, Fd, Fr);\n    #else // IRIDESCENCE\n    baseIBL(surface, info, E, Fd, Fr);\n    #endif // IRIDESCENCE\n\n    // sheen\n    #ifdef SHEEN\n    sheenIBL(surface, info, Fd, Fr);\n    #endif // SHEEN\n\n    // clear coat\n    #ifdef CLEARCOAT\n    clearCoatIBL(surface, info, Fd, Fr);\n    #endif // CLEARCOAT\n\n    #ifdef TRANSMISSION\n    Fd *= (1.0 - surface.transmission);\n    vec3 Ft = transmissionIBL(surface, info, E);\n    #endif // TRANSMISSION\n\n    vec3 gi = Fd + Fr;\n\n    #ifdef TRANSMISSION\n    gi += Ft;\n    #endif // TRANSMISSION\n\n    return gi;\n}\n\n#endif // pbrGI_lib';

  // src/layaAir/laya/d3/shader/pbr/pbrCommon.glsl
  var pbrCommon_default = "#if !defined(pbrCommon_lib)\n    #define pbrCommon_lib\n\n// varying\nvarying vec3 v_PositionWS;\n\n// todo\nvarying vec3 v_NormalWS;\nvarying vec3 v_TangentWS;\nvarying vec3 v_BiNormalWS;\n\n    #ifdef UV\nvarying vec2 v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\nvarying vec2 v_Texcoord1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\nvarying vec4 v_VertexColor;\n    #endif // COLOR\n\n// \u8BB0\u5F55\u9876\u70B9\u4FE1\u606F, \u7528\u4E8E\u7531vs\u5411fs\u4F20\u9012\u6570\u636E\nstruct PixelParams {\n\n    vec3 positionWS;\n\n    vec3 normalWS;\n    vec3 tangentWS;\n    vec3 biNormalWS;\n    mat3 TBN;\n\n    #ifdef UV\n    vec2 uv0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\n    vec2 uv1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n};\n\n#endif // pbrCommon_lib";

  // src/layaAir/laya/d3/shader/pbr/pbrVertex.glsl
  var pbrVertex_default = '#if !defined(pbrVertex_lib)\n    #define pbrVertex_lib\n\n    #include "ShadingVertex.glsl";\n\n    #ifdef THICKNESS\n// xyz: world scale, w: length(xyz)\nvarying vec4 v_WorldScale;\n    #endif // THICKNESS\n\nvoid initPixelParams(inout PixelParams params, in Vertex vertex)\n{\n    shadingPixelParams(params, vertex);\n    sharePixelParams(params);\n\n    #ifdef THICKNESS\n    mat4 worldMat = getWorldMatrix();\n    v_WorldScale.x = length(vec3(worldMat[0].xyz));\n    v_WorldScale.y = length(vec3(worldMat[1].xyz));\n    v_WorldScale.z = length(vec3(worldMat[2].xyz));\n    v_WorldScale.w = length(v_WorldScale.xyz);\n    #endif // THICKNESS\n}\n\n#endif // pbrVertex_lib';

  // src/layaAir/laya/d3/shader/pbr/pbrFrag.glsl
  var pbrFrag_default = '//\u517C\u5BB9WGSL\n#if !defined(pbrFrag_lib)\n    #define pbrFrag_lib\n\n    #include "PBRLighting.glsl";\n\n    #ifdef THICKNESS\n// xyz: world scale, w: length(xyz)\nvarying vec4 v_WorldScale;\n    #endif // THICKNESS\n\nvoid getPixelInfo(inout PixelInfo info, const in PixelParams pixel, const in Surface surface)\n{\n    info.positionWS = pixel.positionWS;\n    info.vertexNormalWS = pixel.normalWS;\n\n    #ifdef TANGENT\n    info.normalWS = normalize(pixel.TBN * surface.normalTS);\n    #else // TANGENT\n    info.normalWS = pixel.normalWS;\n    #endif // TANGENT\n\n    info.tangentWS = pixel.tangentWS;\n    info.biNormalWS = pixel.biNormalWS;\n\n    info.viewDir = normalize(u_CameraPos - info.positionWS);\n    info.NoV = min(max(dot(info.normalWS, info.viewDir), MIN_N_DOT_V), 1.0);\n\n    info.dfg = prefilteredDFG_LUT(surface.perceptualRoughness, info.NoV);\n\n    #ifdef SHEEN\n    info.energyCompensation = vec3(1.0);\n    #else // SHEEN\n    info.energyCompensation = (1.0 + surface.f0 * (1.0 / info.dfg.y - 1.0));\n    #endif // SHEEN\n\n    #ifdef IRIDESCENCE\n    info.iridescenceFresnel = evalIridescence(1.0, surface.iridescenceIor, info.NoV, surface.iridescenceThickness, surface.f0);\n    #endif // IRIDESCENCE\n\n    #ifdef SHEEN\n    info.sheenDfg = prefilteredDFG_LUT(surface.sheenPerceptualRoughness, info.NoV).z;\n    info.sheenScaling = 1.0 - vecmax(surface.sheenColor) * info.sheenDfg;\n    #endif // SHEEN\n\n    #ifdef CLEARCOAT\n	#ifdef CLEARCOAT_NORMAL\n    info.clearCoatNormal = normalize(pixel.TBN * surface.clearCoatNormalTS);\n	#else // CLEARCOAT_NORMAL\n    info.clearCoatNormal = info.vertexNormalWS;\n	#endif // CLEARCOAT_NORMAL\n    info.clearCoatNoV = min(max(dot(info.clearCoatNormal, info.viewDir), MIN_N_DOT_V), 1.0);\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    mat3 anisotropyTBN = mat3(info.tangentWS, info.biNormalWS * -1.0, info.normalWS);\n    info.anisotropicT = anisotropyTBN * normalize(vec3(surface.anisotropyDirection, 0.0));\n    info.anisotropicB = cross(info.vertexNormalWS, info.anisotropicT);\n    info.ToV = dot(info.anisotropicT, info.viewDir);\n    info.BoV = dot(info.anisotropicB, info.viewDir);\n    info.at = mix(surface.roughness, 1.0, pow2(surface.anisotropy));\n    info.ab = surface.roughness;\n    #endif // ANISOTROPIC\n\n    #ifdef THICKNESS\n    info.worldScale = v_WorldScale;\n    #endif // THICKNESS\n\n    #ifdef LIGHTMAP\n	#ifdef UV1\n    info.lightmapUV = pixel.uv1;\n	#endif // UV1\n    #endif // LIGHTMAP\n}\n\nvec3 PBRLighting(const in Surface surface, const in PixelInfo info)\n{\n    vec3 lightColor = vec3(0.0);\n    #ifdef DIRECTIONLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n	{\n	    if (i >= DirectionCount) \n            break;\n	    DirectionLight directionLight = getDirectionLight(i, info.positionWS);\n\n	    if (directionLight.lightMode == LightMode_Mix)\n		{\n		    continue;\n		}\n\n        Light light = getLight(directionLight);\n        lightColor += PBRLighting(surface, info, light) * light.attenuation;\n	}\n    #endif // DIRECTIONLIGHT\n\n    #if defined(POINTLIGHT) || defined(SPOTLIGHT)\n    ivec4 clusterInfo = getClusterInfo(u_View, u_Viewport, info.positionWS, gl_FragCoord, u_ProjectionParams);\n    #endif // POINTLIGHT || SPOTLIGHT\n\n    #ifdef POINTLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n	{\n        if (i >= clusterInfo.x)\n		    break;\n\n	    PointLight pointLight = getPointLight(i, clusterInfo, info.positionWS);\n\n	    if (pointLight.lightMode == LightMode_Mix)\n		{\n		    continue;\n		}\n\n        Light light = getLight(pointLight, info.normalWS, info.positionWS);\n        lightColor += PBRLighting(surface, info, light) * light.attenuation;\n	}\n    #endif // POINTLIGHT\n\n    #ifdef SPOTLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n	{\n	    if (i >= clusterInfo.y) \n            break;\n        \n	    SpotLight spotLight = getSpotLight(i, clusterInfo, info.positionWS);\n	    \n        if (spotLight.lightMode == LightMode_Mix)\n		{\n		    continue;\n		}\n\n        Light light = getLight(spotLight, info.normalWS, info.positionWS);\n        lightColor += PBRLighting(surface, info, light) * light.attenuation;\n	}\n    #endif // SPOTLIGHT\n\n    vec3 giColor = PBRGI(surface, info);\n\n    vec3 color = lightColor + giColor;\n\n    #ifdef EMISSION\n    color += surface.emissionColor;\n    #endif //  EMISSION\n    return color;\n}\n\n#endif // pbrFrag_lib';

  // src/layaAir/laya/d3/shader/pbr/pbrMetallicFrag.glsl
  var pbrMetallicFrag_default = '#if !defined(PBRMetallic_lib)\n    #define PBRMetallic_lib\n\n    #include "ShadingFrag.glsl";\n\n    #include "PBRFrag.glsl";\n\nstruct SurfaceInputs {\n    vec3 diffuseColor;\n    float alpha;\n    float alphaTest;\n    float metallic;\n    float smoothness;\n    float occlusion;\n    vec3 emissionColor;\n    vec3 normalTS;\n\n    #ifdef CLEARCOAT\n    float clearCoat;\n    float clearCoatRoughness;\n	#ifdef CLEARCOAT_NORMAL\n    vec3 clearCoatNormalTS;\n	#endif // CLEARCOAT_NORMAL\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    float anisotropy;\n    vec2 anisotropyDirection;\n    #endif // ANISOTROPIC\n};\n\nvoid initSurface(inout Surface surface, const in SurfaceInputs inputs, const in PixelParams pixel)\n{\n    surface.alpha = inputs.alpha;\n\n    surface.normalTS = inputs.normalTS;\n\n    vec3 baseColor = inputs.diffuseColor;\n    float metallic = inputs.metallic;\n    float perceptualRoughness = 1.0 - inputs.smoothness;\n\n    // default ior 1.5\n    float ior = 1.5;\n    surface.ior = 1.5;\n    vec3 f0 = vec3(0.04, 0.04, 0.04);\n\n    surface.perceptualRoughness = clamp(perceptualRoughness, MIN_PERCEPTUAL_ROUGHNESS, 1.0);\n    surface.roughness = surface.perceptualRoughness * surface.perceptualRoughness;\n    surface.diffuseColor = computeDiffuse(baseColor, metallic);\n    surface.f0 = computeF0(f0, baseColor, metallic);\n    surface.f90 = computeF90(surface.f0);\n\n    surface.occlusion = inputs.occlusion;\n\n    #ifdef EMISSION\n    surface.emissionColor = inputs.emissionColor;\n    #endif // EMISSION\n\n    #ifdef CLEARCOAT\n    surface.clearCoat = inputs.clearCoat;\n    surface.clearCoatPerceptualRoughness = clamp(inputs.clearCoatRoughness, MIN_PERCEPTUAL_ROUGHNESS, 1.0);\n    surface.clearCoatRoughness = surface.clearCoatPerceptualRoughness * surface.clearCoatPerceptualRoughness;\n	#ifdef CLEARCOAT_NORMAL\n    surface.clearCoatNormalTS = inputs.clearCoatNormalTS;\n	#endif // CLEARCOAT_NORMAL\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    surface.anisotropy = inputs.anisotropy;\n    surface.anisotropyDirection = inputs.anisotropyDirection;\n    #endif // ANISOTROPIC\n}\n\nvec4 PBR_Metallic_Flow(const in SurfaceInputs inputs, in PixelParams pixel)\n{\n    #ifdef ALPHATEST\n    if (inputs.alpha < inputs.alphaTest)\n	{\n	    discard;\n	}\n    #endif // ALPHATEST\n\n    Surface surface;\n    initSurface(surface, inputs, pixel);\n\n    PixelInfo info;\n    getPixelInfo(info, pixel, surface);\n\n    vec3 surfaceColor = vec3(0.0);\n    surfaceColor += PBRLighting(surface, info);\n\n    return vec4(surfaceColor, surface.alpha);\n}\n\n#endif // PBRMetallic_lib\n';

