  // src/layaAir/laya/d3/shader/utils/BakedBoneMatrixSampler.glsl
  var BakedBoneMatrixSampler_default = "#if !defined(BakeBoneAnimSampler_lib)\n    #define BakeBoneAnimSampler_lib\n\nmat4 loadBakedMatMatrix(float FramePos, float boneIndices, float offset)\n{\n    vec2 uv;\n    float PixelPos = FramePos + boneIndices * 4.0;\n    float halfOffset = offset * 0.5;\n    float uvoffset = PixelPos / u_SimpleAnimatorTextureSize;\n    uv.y = floor(uvoffset) * offset + halfOffset;\n    uv.x = mod(float(PixelPos), u_SimpleAnimatorTextureSize) * offset + halfOffset;\n    vec4 mat0row = texture2D(u_SimpleAnimatorTexture, uv);\n    uv.x += offset;\n    vec4 mat1row = texture2D(u_SimpleAnimatorTexture, uv);\n    uv.x += offset;\n    vec4 mat2row = texture2D(u_SimpleAnimatorTexture, uv);\n    uv.x += offset;\n    vec4 mat3row = texture2D(u_SimpleAnimatorTexture, uv);\n    mat4 m = mat4(mat0row.x, mat0row.y, mat0row.z, mat0row.w,\n	mat1row.x, mat1row.y, mat1row.z, mat1row.w,\n	mat2row.x, mat2row.y, mat2row.z, mat2row.w,\n	mat3row.x, mat3row.y, mat3row.z, mat3row.w);\n    return m;\n}\n\n#endif // BakeBoneAnimSampler_lib";

  // src/layaAir/laya/d3/shader/common/MorphTarget.glsl
  var MorphTarget_default = "#if !defined(MorphTarget_lib)\n    #define MorphTarget_lib\n\n    #ifdef GRAPHICS_API_GLES3\n\n/// static mesh property\nuniform sampler2DArray u_MorphTargetsTex;\n// xy: tex size, z: attribute count\nuniform vec4 u_MorphParams;\nuniform vec4 u_MorphAttrOffset;\n\n	#define Morph_TexWidth	   u_MorphParams.x\n	#define Morph_TexHeight	   u_MorphParams.y\n	#define Morph_AttributeNum u_MorphParams.z\n	#define Morph_TargetNum	   u_MorphParams.w\n\n	#define Morph_PositionOffset u_MorphAttrOffset.x\n	#define Morph_NormalOffset   u_MorphAttrOffset.y\n	#define Morph_TangentOffset  u_MorphAttrOffset.z\n\n//#define MORPH_MAX_COUNT 32 //\u517C\u5BB9WGSL\n\n/// dynamic params\n//uniform float u_MorphActiveTargets[MORPH_MAX_COUNT];\n//uniform float u_MorphTargetWeights[MORPH_MAX_COUNT];\nuniform vec4 u_MorphActiveTargets[MORPH_MAX_COUNT];\nuniform int u_MorphTargetActiveCount;\n\n	#define MORPH_ACTIVE_COUNT u_MorphTargetActiveCount\n\nvec4 sampleMorphTargets(in int vertexID, in float targetID)\n{\n    int v = vertexID / int(Morph_TexWidth);\n    int u = vertexID - v * int(Morph_TexWidth);\n\n    vec3 uvw = vec3((float(u) + 0.5) / Morph_TexWidth, (float(v) + 0.5) / Morph_TexHeight, targetID);\n\n    return texture(u_MorphTargetsTex, uvw);\n}\n\nvec3 positionMorph(in vec3 position)\n{\n    int vertexID = gl_VertexID * int(Morph_AttributeNum) + int(Morph_PositionOffset);\n\n    for (int i = 0; i < MORPH_ACTIVE_COUNT; i++)\n	{\n	    float index = u_MorphActiveTargets[i].x;\n		float weight = u_MorphActiveTargets[i].y;\n\n	    position += sampleMorphTargets(vertexID, index).xyz * weight;\n	}\n\n    return position;\n}\n\nvec3 normalMorph(in vec3 normal)\n{\n    int vertexID = gl_VertexID * int(Morph_AttributeNum) + int(Morph_NormalOffset);\n    for (int i = 0; i < MORPH_ACTIVE_COUNT; i++)\n	{\n	    float index = u_MorphActiveTargets[i].x;\n		float weight = u_MorphActiveTargets[i].y;\n\n	    normal += sampleMorphTargets(vertexID, index).xyz * weight;\n	}\n\n    return normal;\n}\n\nvec4 tangentMorph(in vec4 tangent)\n{\n    int vertexID = gl_VertexID * int(Morph_AttributeNum) + int(Morph_TangentOffset);\n    for (int i = 0; i < MORPH_ACTIVE_COUNT; i++)\n	{\n	    float index = u_MorphActiveTargets[i].x;\n		float weight = u_MorphActiveTargets[i].y;\n\n	    vec4 sampleTangent = sampleMorphTargets(vertexID, index);\n\n	    tangent.xyz += sampleTangent.xyz * weight * tangent.w * sampleTangent.w;\n	}\n\n    return tangent;\n}\n\n    #endif // GRAPHICS_API_GLES3\n\n#endif // MorphTarget_lib";

  // src/layaAir/laya/d3/shader/common/VertexCommon.glsl
  var VertexCommon_default = '#if !defined(VertexCommon_lib)\n    #define VertexCommon_lib\n\n    #ifdef MORPHTARGETS\n	#include "MorphTarget.glsl";\n    #endif // MORPHTARGETS\n\nstruct Vertex {\n\n    vec3 positionOS;\n\n    vec3 normalOS;\n\n    #ifdef TANGENT\n    vec4 tangentOS;\n    #endif // TANGENT\n\n    // todo  uv define ?\n    #ifdef UV\n    vec2 texCoord0;\n    #endif // UV\n\n    #ifdef UV1\n    vec2 texCoord1;\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n\n    #ifdef LIGHTMAP\n    vec4 lightmapScaleOffset;\n	#endif LIGHTMAP\n};\n\n/**\n * vertex position\n */\nvec4 getVertexPosition()\n{\n    vec4 position = a_Position;\n\n    #ifdef MORPHTARGETS\n	#ifdef MORPHTARGETS_POSITION\n    #ifdef GRAPHICS_API_GLES3\n    position.xyz = positionMorph(position.xyz);\n    #endif // GRAPHICS_API_GLES3\n	#endif // MORPHTARGETS_POSITION\n    #endif // MORPHTARGETS\n\n    return position;\n}\n\nvec3 getVertexNormal()\n{\n    vec3 normal = a_Normal.xyz;\n    #ifdef MORPHTARGETS\n	#ifdef MORPHTARGETS_NORMAL\n    #ifdef GRAPHICS_API_GLES3\n    normal.xyz = normalMorph(normal);\n    #endif // GRAPHICS_API_GLES3\n	#endif // MORPHTARGETS_NORMAL\n    #endif // MORPHTARGETS\n\n    return normal;\n}\n\n    #ifdef TANGENT\nvec4 getVertexTangent()\n{\n    vec4 tangent = a_Tangent0;\n\n	#ifdef MORPHTARGETS\n	#ifdef MORPHTARGETS_TANGENT\n    #ifdef GRAPHICS_API_GLES3\n    tangent = tangentMorph(tangent);\n    #endif // GRAPHICS_API_GLES3\n	#endif // MORPHTARGETS_TANGENT\n	#endif // MORPHTARGETS\n\n    return tangent;\n}\n    #endif // TANGENT\n\n    #ifdef LIGHTMAP\n#ifndef GPU_INSTANCE\n    uniform vec4 u_LightmapScaleOffset;\n#endif // GPU_INSTANCE\n\nvec4 getLightmapScaleOffset(){\n    \n    #ifdef GPU_INSTANCE\n        return a_LightmapScaleOffset;\n    #else\n        return u_LightmapScaleOffset;\n    #endif // GPU_INSTANCE\n}\n    #endif // LIGHTMAP\n\nvoid getVertexParams(inout Vertex vertex)\n{\n    vertex.positionOS = getVertexPosition().xyz;\n\n    vertex.normalOS = getVertexNormal();\n\n    #ifdef TANGENT\n    vertex.tangentOS = getVertexTangent();\n    #endif // TANGENT\n\n    #ifdef UV\n    vertex.texCoord0 = a_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n    vertex.texCoord1 = a_Texcoord1;\n    #endif // UV1\n\n    #ifdef COLOR\n    // consider vertexColor is gamma\n    vertex.vertexColor = vec4(pow(a_Color.rgb, vec3(2.2)), a_Color.a);\n    #endif // COLOR\n\n    #ifdef LIGHTMAP\n    vertex.lightmapScaleOffset = getLightmapScaleOffset();\n	#endif LIGHTMAP\n}\n\n#endif // VertexCommon_lib';

