  var ShadingCommon_default = "#if !defined(ShadingCommon_lib)\n    #define ShadingCommon_lib\n\n// varying\nvarying vec3 v_PositionWS;\n// todo\nvarying vec3 v_NormalWS;\nvarying vec3 v_TangentWS;\nvarying vec3 v_BiNormalWS;\n\n    #ifdef UV\nvarying vec2 v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\nvarying vec2 v_Texcoord1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\nvarying vec4 v_VertexColor;\n    #endif // COLOR\n\n// \u8BB0\u5F55\u9876\u70B9\u4FE1\u606F, \u7528\u4E8E\u7531vs\u5411fs\u4F20\u9012\u6570\u636E\nstruct PixelParams {\n    vec3 positionWS;\n\n    // todo\n    vec3 normalWS;\n    vec3 tangentWS;\n    vec3 biNormalWS;\n    mat3 TBN;\n\n    #ifdef UV\n    vec2 uv0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\n    vec2 uv1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n};\n\n#endif // ShadingCommon_lib";

  // src/layaAir/laya/d3/shader/common/ShadingVertex.glsl
  var ShadingVertex_default = '#if !defined(ShadingVertex_lib)\n    #define ShadingVertex_lib\n\n    #include "ShadingCommon.glsl";\n\nvoid sharePixelParams(const in PixelParams params)\n{\n    v_PositionWS = params.positionWS;\n\n    v_NormalWS = params.normalWS;\n    v_TangentWS = params.tangentWS;\n    v_BiNormalWS = params.biNormalWS;\n\n    #ifdef UV\n    v_Texcoord0 = params.uv0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\n    v_Texcoord1 = params.uv1;\n	#endif LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    v_VertexColor = params.vertexColor;\n    #endif // COLOR\n}\n\nvoid shadingPixelParams(inout PixelParams params, in Vertex vertex)\n{\n    mat4 worldMat = getWorldMatrix();\n    vec4 pos = (worldMat * vec4(vertex.positionOS, 1.0));\n    params.positionWS = pos.xyz / pos.w;\n\n    mat3 normalMat = transpose(inverse(mat3(worldMat)));\n    params.normalWS = normalize((normalMat * vertex.normalOS).xyz);\n\n    #ifdef TANGENT\n    params.tangentWS = normalize((normalMat * vertex.tangentOS.xyz).xyz);\n    params.tangentWS *= WorldInvertFront;\n    params.biNormalWS = normalize(cross(params.normalWS, params.tangentWS) * sign(vertex.tangentOS.w));\n    #else // TANGENT\n    params.tangentWS = vec3(1.0, 0.0, 0.0);\n    params.tangentWS *= WorldInvertFront;\n    params.biNormalWS = normalize(cross(params.normalWS, params.tangentWS));\n    #endif // TANGENT\n\n    #ifdef UV\n    params.uv0 = vertex.texCoord0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\n    params.uv1 = tranformLightMapUV(vertex.texCoord1, vertex.lightmapScaleOffset);\n	#endif LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    params.vertexColor = vertex.vertexColor;\n    #endif // COLOR\n}\n\n#endif // ShadingVertex_lib';

  // src/layaAir/laya/d3/shader/common/ShadingFrag.glsl
  var ShadingFrag_default = '#if !defined(ShadingFrag_lib)\n    #define ShadingFrag_lib\n\n    #include "ShadingCommon.glsl";\n\n    #define _InvertNormal (float(gl_FrontFacing) * 2.0 - 1.0);\n\nvoid getPixelParams(inout PixelParams params)\n{\n    params.positionWS = v_PositionWS;\n\n    float invertN = _InvertNormal;\n\n    params.normalWS = normalize(v_NormalWS * invertN);\n    params.tangentWS = normalize(v_TangentWS * invertN);\n    params.biNormalWS = normalize(v_BiNormalWS * invertN);\n\n    params.TBN = mat3(params.tangentWS, params.biNormalWS, params.normalWS);\n\n    #ifdef UV\n    params.uv0 = v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\n    params.uv1 = v_Texcoord1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    params.vertexColor = v_VertexColor;\n    #endif // COLOR\n}\n\n#endif // ShadingFrag_lib';

