  // src/layaAir/laya/d3/shader/unlit/Unlit.vs
  var Unlit_default = '\n#define SHADER_NAME UnlitVS\n\n#include "Math.glsl";\n\n#include "Scene.glsl";\n#include "SceneFogInput.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DVertex.glsl";\n\n#include "VertexCommon.glsl";\n\n#ifdef UV\nvarying vec2 v_Texcoord0;\n#endif // UV\n\n#ifdef COLOR\nvarying vec4 v_VertexColor;\n#endif // COLOR\n\nvoid main()\n{\n    Vertex vertex;\n    getVertexParams(vertex);\n\n#ifdef UV\n    v_Texcoord0 = transformUV(vertex.texCoord0, u_TilingOffset);\n#endif // UV\n\n#ifdef COLOR\n    v_VertexColor = vertex.vertexColor;\n#endif // COLOR\n\n    mat4 worldMat = getWorldMatrix();\n    vec4 pos = (worldMat * vec4(vertex.positionOS, 1.0));\n    vec3 positionWS = pos.xyz / pos.w;\n\n    gl_Position = getPositionCS(positionWS);\n\n    gl_Position = remapPositionZ(gl_Position);\n\n#ifdef FOG\n    FogHandle(gl_Position.z);\n#endif\n}\n';

  // src/layaAir/laya/d3/shader/unlit/Unlit.fs
  var Unlit_default2 = '\n#define SHADER_NAME UNLITFS\n\n#include "Color.glsl";\n\n#include "Scene.glsl";\n#include "SceneFog.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DFrag.glsl";\n\n#ifdef UV\nvarying vec2 v_Texcoord0;\n#endif // UV\n\n#ifdef COLOR\nvarying vec4 v_VertexColor;\n#endif // COLOR\n\nvoid main()\n{\n    vec3 color = u_AlbedoColor.rgb;\n    float alpha = u_AlbedoColor.a;\n\n#ifdef COLOR\n    #ifdef ENABLEVERTEXCOLOR\n    vec4 vertexColor = v_VertexColor;\n    color *= vertexColor.rgb;\n    alpha *= vertexColor.a;\n    #endif // ENABLEVERTEXCOLOR\n#endif // COLOR\n\n#ifdef UV\n    vec2 uv = v_Texcoord0;\n\n    #ifdef ALBEDOTEXTURE\n    vec4 albedoSampler = texture2D(u_AlbedoTexture, uv);\n\n	#ifdef Gamma_u_AlbedoTexture\n    albedoSampler = gammaToLinear(albedoSampler);\n	#endif // Gamma_u_AlbedoTexture\n\n    color *= albedoSampler.rgb;\n    alpha *= albedoSampler.a;\n    #endif // ALBEDOTEXTURE\n#endif // UV\n\n#ifdef ALPHATEST\n    if (alpha < u_AlphaTestValue)\n	discard;\n#endif // ALPHATEST\n\n#ifdef FOG\n    color = scenUnlitFog(color);\n#endif // FOG\n\n    gl_FragColor = vec4(color, alpha);\n    gl_FragColor = outputTransform(gl_FragColor);\n}';

  // src/layaAir/laya/d3/shader/depth/Depth.vs
  var Depth_default = '#define SHADER_NAME DepthVS\n\n#include "DepthVertex.glsl";\n\nvoid main()\n{\n    Vertex vertex;\n    getVertexParams(vertex);\n\n    mat4 worldMat = getWorldMatrix();\n    vec4 pos = (worldMat * vec4(vertex.positionOS, 1.0));\n    vec3 positionWS = pos.xyz / pos.w;\n\n    mat4 normalMat = transpose(inverse(worldMat));\n    vec3 normalWS = normalize((normalMat * vec4(vertex.normalOS, 0.0)).xyz);\n\n    vec4 positionCS = DepthPositionCS(positionWS, normalWS);\n    gl_Position = remapPositionZ(positionCS);\n}';

