  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhongCommon.glsl
  var BlinnPhongCommon_default = "#if !defined(BlinnPhongCommon_lib)\n    #define BlinnPhongCommon_lib\n\n// varying\nvarying vec3 v_PositionWS;\n// todo\nvarying vec3 v_NormalWS;\nvarying vec3 v_TangentWS;\nvarying vec3 v_BiNormalWS;\n\n    #ifdef UV\nvarying vec2 v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\nvarying vec2 v_Texcoord1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\nvarying vec4 v_VertexColor;\n    #endif // COLOR\n\n// \u8BB0\u5F55\u9876\u70B9\u4FE1\u606F, \u7528\u4E8E\u7531vs\u5411fs\u4F20\u9012\u6570\u636E\nstruct PixelParams {\n    vec3 positionWS;\n\n    vec3 normalWS;\n    vec3 tangentWS;\n    vec3 biNormalWS;\n    mat3 TBN;\n\n    #ifdef UV\n    vec2 uv0;\n    #endif // UV\n\n    #ifdef UV1\n	#ifdef LIGHTMAP\n    vec2 uv1;\n	#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n};\n\n#endif // BlinnPhongCommon_lib";

  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhongVertex.glsl
  var BlinnPhongVertex_default = '#if !defined(BlinnPhongVertex_lib)\n    #define BlinnPhongVertex_lib\n\n    #include "ShadingVertex.glsl";\n\nvoid initPixelParams(inout PixelParams params, in Vertex vertex)\n{\n    shadingPixelParams(params, vertex);\n    sharePixelParams(params);\n}\n\n#endif // BlinnPhongVertex_lib';

  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhongFrag.glsl
  var BlinnPhongFrag_default = '#if !defined(BlinnPhongFrag_lib)\n    #define BlinnPhongFrag_lib\n\n    #include "BlinnPhongLighting.glsl";\n\n    #include "ShadingFrag.glsl";\n\nvoid getPixelInfo(inout PixelInfo info, const in PixelParams pixel, const in Surface surface)\n{\n    info.positionWS = pixel.positionWS;\n\n    info.vertexNormalWS = pixel.normalWS;\n\n    #ifdef TANGENT\n    info.normalWS = normalize(pixel.TBN * surface.normalTS);\n    #else // TANGENT\n    info.normalWS = pixel.normalWS;\n    #endif // TANGENT\n\n    info.viewDir = normalize(u_CameraPos - info.positionWS);\n\n    #ifdef LIGHTMAP\n	#ifdef UV1\n    info.lightmapUV = pixel.uv1;\n	#endif // UV1\n    #endif // LIGHTMAP\n}\n\nvec3 BlinnPhongLighting(const in Surface surface, const in PixelParams pixel)\n{\n    PixelInfo info;\n    getPixelInfo(info, pixel, surface);\n\n    vec3 positionWS = info.positionWS;\n    vec3 normalWS = info.normalWS;\n    vec3 v = info.viewDir;\n\n    vec3 lightColor = vec3(0.0, 0.0, 0.0);\n\n    #ifdef DIRECTIONLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n	{\n	    if (i >= DirectionCount) break;\n	    DirectionLight directionLight = getDirectionLight(i, positionWS);\n\n	    if (directionLight.lightMode == LightMode_Mix)\n		{\n		    continue;\n		}\n\n        Light light = getLight(directionLight);\n        lightColor += BlinnPhongLighting(surface, light, info) * light.attenuation;\n	}\n    #endif // DIRECTIONLIGHT\n\n    #if defined(POINTLIGHT) || defined(SPOTLIGHT)\n    ivec4 clusterInfo = getClusterInfo(u_View, u_Viewport, positionWS, gl_FragCoord, u_ProjectionParams);\n    #endif // POINTLIGHT || SPOTLIGHT\n\n    #ifdef POINTLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n	{\n	    if (i >= clusterInfo.x) break;\n	    PointLight pointLight = getPointLight(i, clusterInfo, positionWS);\n\n	    if (pointLight.lightMode == LightMode_Mix)\n		{\n		    continue;\n		}\n\n        Light light = getLight(pointLight, normalWS, positionWS);\n        lightColor += BlinnPhongLighting(surface, light, info) * light.attenuation;\n	}\n    #endif // POINTLIGHT\n\n    #ifdef SPOTLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n	{\n	    if (i >= clusterInfo.y) break;\n\n	    SpotLight spotLight = getSpotLight(i, clusterInfo, positionWS);\n\n	    if (spotLight.lightMode == LightMode_Mix)\n		{\n		    continue;\n		}\n\n        Light light = getLight(spotLight, normalWS, positionWS);\n        lightColor += BlinnPhongLighting(surface, light, info) * light.attenuation;\n	}\n    #endif // SPOTLIGHT\n\n    vec3 giColor = BlinnPhongGI(surface, info);\n\n    return lightColor + giColor;\n}\n\n#endif // BlinnPhongFrag_lib';

  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhong.vs
  var BlinnPhong_default = '#define SHADER_NAME BlinnPhongVS\n\n#include "Math.glsl";\n\n#include "Scene.glsl";\n#include "SceneFogInput.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DVertex.glsl";\n\n#include "VertexCommon.glsl";\n\n#include "BlinnPhongVertex.glsl";\n\nvoid main()\n{\n    Vertex vertex;\n    getVertexParams(vertex);\n\n    PixelParams pixel;\n    initPixelParams(pixel, vertex);\n\n    gl_Position = getPositionCS(pixel.positionWS);\n\n    gl_Position = remapPositionZ(gl_Position);\n\n#ifdef FOG\n    FogHandle(gl_Position.z);\n#endif\n}\n';

  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhong.fs
  var BlinnPhong_default2 = '#define SHADER_NAME BlinnPhongFS\n\n#include "Color.glsl";\n\n#include "Scene.glsl";\n#include "SceneFog.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DFrag.glsl";\n\n#include "BlinnPhongFrag.glsl";\n\nvoid getBinnPhongSurfaceParams(inout Surface surface, in PixelParams pixel)\n{\n#ifdef UV\n    vec2 uv = transformUV(pixel.uv0, u_TilingOffset);\n#else // UV\n    vec2 uv = vec2(0.0);\n#endif // UV\n\n    surface.diffuseColor = u_DiffuseColor.rgb;\n    surface.alpha = u_DiffuseColor.a;\n\n#ifdef COLOR\n    #ifdef ENABLEVERTEXCOLOR\n    surface.diffuseColor *= pixel.vertexColor.xyz;\n    surface.alpha *= pixel.vertexColor.a;\n    #endif // ENABLEVERTEXCOLOR\n#endif // COLOR\n\n#ifdef DIFFUSEMAP\n    vec4 diffuseSampler = texture2D(u_DiffuseTexture, uv);\n    #ifdef Gamma_u_DiffuseTexture\n    diffuseSampler = gammaToLinear(diffuseSampler);\n    #endif // Gamma_u_DiffuseTexture\n    surface.diffuseColor *= u_DiffuseColor.rgb * diffuseSampler.rgb * u_AlbedoIntensity;\n    surface.alpha *= diffuseSampler.a;\n#endif // DIFFUSEMAP\n\n    surface.diffuseColor *= u_AlbedoIntensity;\n\n    surface.normalTS = vec3(0.0, 0.0, 1.0);\n#ifdef NORMALMAP\n    vec3 normalSampler = texture2D(u_NormalTexture, uv).rgb;\n    normalSampler = normalize(normalSampler * 2.0 - 1.0);\n    normalSampler.y *= -1.0;\n    surface.normalTS = normalSampler;\n#endif // NORMALMAP\n\n#ifdef SPECULARMAP\n    vec4 specularSampler = texture2D(u_SpecularTexture, uv);\n    #ifdef Gamma_u_SpecularTexture\n    specularSampler = gammaToLinear(specularSampler);\n    #endif // Gamma_u_SpecularTexture\n    surface.gloss = specularSampler.rgb;\n#else // SPECULARMAP\n    #ifdef DIFFUSEMAP\n    surface.gloss = vec3(diffuseSampler.a);\n    #else // DIFFUSEMAP\n    surface.gloss = vec3(1.0, 1.0, 1.0);\n    #endif // DIFFUSEMAP\n#endif // SPECULARMAP\n    surface.specularColor = u_MaterialSpecular.rgb;\n    surface.shininess = u_Shininess;\n}\n\nvoid main()\n{\n    PixelParams pixel;\n    getPixelParams(pixel);\n\n    Surface surface;\n    getBinnPhongSurfaceParams(surface, pixel);\n\n#ifdef ALPHATEST\n    if (surface.alpha < u_AlphaTestValue)\n	{\n	    discard;\n	}\n#endif // ALPHATEST\n\n    vec3 surfaceColor = vec3(0.0);\n\n    surfaceColor = BlinnPhongLighting(surface, pixel);\n\n#ifdef FOG\n    surfaceColor = sceneLitFog(surfaceColor);\n#endif // FOG\n\n    gl_FragColor = vec4(surfaceColor, surface.alpha);\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}\n';

  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhongDepthNormal.vs
  var BlinnPhongDepthNormal_default = '#define SHADER_NAME BlinnPhongDephtNormalVS\n\n#include "Math.glsl";\n\n#include "Camera.glsl";\n\n#include "Sprite3DVertex.glsl";\n\n#include "VertexCommon.glsl";\n\n#include "BlinnPhongVertex.glsl";\n\nvarying vec4 v_PositionCS;\n\nvoid main()\n{\n    Vertex vertex;\n    getVertexParams(vertex);\n\n    PixelParams pixel;\n    initPixelParams(pixel, vertex);\n\n    vec4 positionCS = getPositionCS(pixel.positionWS);\n    v_PositionCS = positionCS;\n    gl_Position = positionCS;\n    gl_Position = remapPositionZ(gl_Position);\n}';

  // src/layaAir/laya/d3/shader/blinnphong/BlinnPhongDepthNormal.fs
  var BlinnPhongDepthNormal_default2 = '#define SHADER_NAME BlinnPhongDephtNormalFS\n\n#include "Color.glsl";\n\n#include "Scene.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DFrag.glsl";\n\n#include "ShadingFrag.glsl";\n\n#include "DepthNormalFrag.glsl";\n\nvarying vec4 v_PositionCS;\n\nvoid main()\n{\n    PixelParams pixel;\n    getPixelParams(pixel);\n\n    vec3 normalWS = pixel.normalWS;\n\n#ifdef NORMALMAP\n    #ifdef UV\n\n    vec2 uv = transformUV(pixel.uv0, u_TilingOffset);\n    vec3 normalSampler = texture2D(u_NormalTexture, uv).rgb;\n    normalSampler = normalize(normalSampler * 2.0 - 1.0);\n    normalSampler.y *= -1.0;\n    vec3 normalTS = normalSampler;\n    normalWS = normalize(pixel.TBN * normalTS);\n\n    #endif // UV\n#endif // NORMALMAP\n\n    vec4 positionCS = v_PositionCS;\n\n    vec4 dephtNormal = encodeDepthNormal(positionCS, normalWS);\n\n    gl_FragColor = dephtNormal;\n}';

