  var pbrStandard_default = '#define SHADER_NAME PBRStandardVS\n\n#include "Math.glsl";\n\n#include "Scene.glsl";\n#include "SceneFogInput.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DVertex.glsl";\n\n#include "VertexCommon.glsl";\n\n#include "PBRVertex.glsl";\n\n#if defined(DETAILTEXTURE) || defined(DETAILNORMAL)\nvarying vec2 v_DetailUV;\n#endif\n\nvoid main()\n{\n    Vertex vertex;\n    getVertexParams(vertex);\n\n    PixelParams pixel;\n    initPixelParams(pixel, vertex);\n\n#if defined(DETAILTEXTURE) || defined(DETAILNORMAL)\n    #ifdef UV\n    v_DetailUV = transformUV(vertex.texCoord0, u_DetailTillingOffset);\n    #else // UV\n    v_DetailUV = vec2(0.0);\n    #endif\n#endif\n\n    gl_Position = getPositionCS(pixel.positionWS);\n\n    gl_Position = remapPositionZ(gl_Position);\n\n#ifdef FOG\n    FogHandle(gl_Position.z);\n#endif\n}';

  // src/layaAir/laya/d3/shader/pbr/pbrStandard.fs
  var pbrStandard_default2 = '#define SHADER_NAME PBRStandardFS\n\n#include "Color.glsl";\n\n#include "Scene.glsl";\n#include "SceneFog.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DFrag.glsl";\n\n#include "PBRMetallicFrag.glsl";\n\n#if defined(DETAILTEXTURE) || defined(DETAILNORMAL)\nvarying vec2 v_DetailUV;\n    #define ColorSpaceDouble vec3(4.59479380, 4.59479380, 4.59479380);\nvec3 BlendNormals(vec3 n1, vec3 n2)\n{\n    return normalize(vec3(n1.xy + n2.xy, n1.z * n2.z));\n}\n#endif // DETAILTEXTURE || DETAILNORMAL\n\nvoid initSurfaceInputs(inout SurfaceInputs inputs, const in PixelParams pixel)\n{\n#ifdef UV\n    vec2 uv = transformUV(pixel.uv0, u_TilingOffset);\n#else // UV\n    vec2 uv = vec2(0.0);\n#endif // UV\n\n    inputs.diffuseColor = u_AlbedoColor.rgb;\n    inputs.alpha = u_AlbedoColor.a;\n\n#ifdef COLOR\n    #ifdef ENABLEVERTEXCOLOR\n    inputs.diffuseColor *= pixel.vertexColor.xyz;\n    inputs.alpha *= pixel.vertexColor.a;\n    #endif // ENABLEVERTEXCOLOR\n#endif // COLOR\n\n    inputs.alphaTest = u_AlphaTestValue;\n\n#ifdef ALBEDOTEXTURE\n    vec4 albedoSampler = texture2D(u_AlbedoTexture, uv);\n    #ifdef Gamma_u_AlbedoTexture\n    albedoSampler = gammaToLinear(albedoSampler);\n    #endif // Gamma_u_AlbedoTexture\n    inputs.diffuseColor *= albedoSampler.rgb;\n    inputs.alpha *= albedoSampler.a;\n#endif // ALBEDOTEXTURE\n\n// Detail Albedo\n#ifdef DETAILTEXTURE\n    vec3 detailSampler = texture2D(u_DetailAlbedoTexture, v_DetailUV).rgb;\n    #ifdef Gamma_u_DetailAlbedoTexture\n    detailSampler = gammaToLinear(detailSampler);\n    #endif // Gamma_u_DetailAlbedoTexture\n    detailSampler *= ColorSpaceDouble;\n    inputs.diffuseColor *= detailSampler;\n#endif\n\n    inputs.normalTS = vec3(0.0, 0.0, 1.0);\n#ifdef NORMALTEXTURE\n    vec3 normalSampler = texture2D(u_NormalTexture, uv).rgb;\n    normalSampler = normalize(normalSampler * 2.0 - 1.0);\n    normalSampler.y *= -1.0;\n    inputs.normalTS = normalScale(normalSampler, u_NormalScale);\n#endif\n\n#ifdef DETAILNORMAL\n    vec3 detailnormalSampler = texture2D(u_DetailNormalTexture, v_DetailUV).rgb;\n    detailnormalSampler = normalize(detailnormalSampler * 2.0 - 1.0);\n    detailnormalSampler.y *= -1.0;\n    detailnormalSampler = normalScale(detailnormalSampler, u_DetailNormalScale);\n    inputs.normalTS = BlendNormals(inputs.normalTS, detailnormalSampler);\n#endif\n\n    inputs.metallic = u_Metallic;\n    inputs.smoothness = u_Smoothness;\n\n#ifdef METALLICGLOSSTEXTURE\n\n    vec4 metallicSampler = texture2D(u_MetallicGlossTexture, uv);\n    #ifdef Gamma_u_MetallicGlossTexture\n    metallicSampler = gammaToLinear(metallicSampler);\n    #endif // Gamma_u_MetallicGlossTexture\n\n    inputs.metallic = metallicSampler.x;\n\n    #ifdef SMOOTHNESSSOURCE_ALBEDOTEXTURE_ALPHA\n	#ifdef ALBEDOTEXTURE\n    inputs.smoothness = (albedoSampler.a * u_Smoothness);\n	#endif // ALBEDOTEXTURE\n    #else // SMOOTHNESSSOURCE_METALLICTEXTURE_ALPHA\n    inputs.smoothness = (metallicSampler.a * u_Smoothness);\n    #endif // SMOOTHNESSSOURCE_ALBEDOTEXTURE_ALPHA\n\n#endif // METALLICGLOSSTEXTURE\n\n    inputs.occlusion = 1.0;\n#ifdef OCCLUSIONTEXTURE\n    vec4 occlusionSampler = texture2D(u_OcclusionTexture, uv);\n    #ifdef Gamma_u_OcclusionTexture\n    occlusionSampler = gammaToLinear(occlusionSampler);\n    #endif // Gamma_u_OcclusionTexture\n\n    float occlusion = occlusionSampler.g;\n    inputs.occlusion = (1.0 - u_OcclusionStrength) + occlusion * u_OcclusionStrength;\n#endif // OCCLUSIONTEXTURE\n\n    inputs.emissionColor = vec3(0.0);\n#ifdef EMISSION\n    inputs.emissionColor = u_EmissionColor.rgb * u_EmissionIntensity;\n    #ifdef EMISSIONTEXTURE\n    vec4 emissionSampler = texture2D(u_EmissionTexture, uv);\n	#ifdef Gamma_u_EmissionTexture\n    emissionSampler = gammaToLinear(emissionSampler);\n	#endif // Gamma_u_EmissionTexture\n    inputs.emissionColor *= emissionSampler.rgb;\n    #endif // EMISSIONTEXTURE\n#endif // EMISSION\n\n#ifdef CLEARCOAT\n    inputs.clearCoat = u_ClearCoatFactor;\n    inputs.clearCoatRoughness = u_ClearCoatRoughness;\n\n    #ifdef CLEARCOATMAP\n    // todo\n    // linear tex no need gamma\n    vec4 clearCoatSampler = texture2D(u_ClearCoatTexture, uv);\n    inputs.clearCoat *= clearCoatSampler.r;\n    #endif // CLEARCOATMAP\n\n    #ifdef CLEARCOAT_ROUGHNESSMAP\n    // todo\n    // linear tex no need gamma\n    vec4 clearcoatSampleRoughness = texture2D(u_ClearCoatRoughnessTexture, uv);\n    inputs.clearCoatRoughness *= clearcoatSampleRoughness.g;\n    #endif // CLEARCOAT_ROUGHNESSMAP\n\n    #ifdef CLEARCOAT_NORMAL\n    vec3 clearCoatNormalSampler = texture2D(u_ClearCoatNormalTexture, uv).rgb;\n    clearCoatNormalSampler = normalize(clearCoatNormalSampler * 2.0 - 1.0);\n    clearCoatNormalSampler.y *= -1.0;\n    inputs.clearCoatNormalTS = clearCoatNormalSampler;\n    #endif // CLEARCOAT_NORMAL\n#endif // CLEARCOAT\n\n#ifdef ANISOTROPIC\n    inputs.anisotropy = u_AnisotropyStrength;\n    vec2 direction = vec2(1.0, 0.0);\n\n    #ifdef ANISOTROPYMAP\n    vec3 anisotropySampler = texture2D(u_AnisotropyTexture, uv).rgb;\n\n    inputs.anisotropy *= anisotropySampler.b;\n    direction = anisotropySampler.xy * 2.0 - 1.0;\n    #endif // ANISOTROPYMAP\n\n    vec2 anisotropyRotation = vec2(cos(u_AnisotropyRotation), sin(u_AnisotropyRotation));\n    mat2 rotationMatrix = mat2(anisotropyRotation.x, anisotropyRotation.y, -anisotropyRotation.y, anisotropyRotation.x);\n    inputs.anisotropyDirection = rotationMatrix * direction;\n\n#endif // ANISOTROPIC\n}\n\nvoid main()\n{\n    PixelParams pixel;\n    getPixelParams(pixel);\n\n    SurfaceInputs inputs;\n    initSurfaceInputs(inputs, pixel);\n\n    vec4 surfaceColor = PBR_Metallic_Flow(inputs, pixel);\n\n#ifdef FOG\n    surfaceColor.rgb = sceneLitFog(surfaceColor.rgb);\n#endif // FOG\n\n    gl_FragColor = surfaceColor;\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}';

  // src/layaAir/laya/d3/shader/pbr/PBRStandardDepthNormal.vs
  var PBRStandardDepthNormal_default = '#define SHADER_NAME PBRStandardDepthNormalVS\n\n#include "Math.glsl";\n\n#include "Camera.glsl";\n\n#include "Sprite3DVertex.glsl";\n\n#include "VertexCommon.glsl";\n\n#include "PBRVertex.glsl";\n\nvarying vec4 v_PositionCS;\n\nvoid main()\n{\n    Vertex vertex;\n    getVertexParams(vertex);\n\n    PixelParams pixel;\n    initPixelParams(pixel, vertex);\n\n    sharePixelParams(pixel);\n\n    vec4 positionCS = getPositionCS(pixel.positionWS);\n    v_PositionCS = positionCS;\n    gl_Position = positionCS;\n    gl_Position = remapPositionZ(gl_Position);\n}';

  // src/layaAir/laya/d3/shader/pbr/PBRStandardDepthNormal.fs
  var PBRStandardDepthNormal_default2 = '#define SHADER_NAME PBRStandardDepthNormalFS\n\n#include "Color.glsl";\n\n#include "Scene.glsl";\n\n#include "Camera.glsl";\n#include "Sprite3DFrag.glsl";\n\n#include "ShadingFrag.glsl";\n\n#include "DepthNormalFrag.glsl";\n\nvarying vec4 v_PositionCS;\n\nvoid main()\n{\n    PixelParams pixel;\n    getPixelParams(pixel);\n\n    vec3 normalWS = pixel.normalWS;\n\n#ifdef NORMALTEXTURE\n    #ifdef UV\n\n    vec2 uv = transformUV(pixel.uv0, u_TilingOffset);\n    vec3 normalSampler = texture2D(u_NormalTexture, uv).rgb;\n    normalSampler = normalize(normalSampler * 2.0 - 1.0);\n    normalSampler.y *= -1.0;\n    vec3 normalTS = normalScale(normalSampler, u_NormalScale);\n    normalWS = normalize(pixel.TBN * normalTS);\n\n    #endif // UV\n#endif // NORMALTEXTURE\n\n    vec4 positionCS = v_PositionCS;\n\n    vec4 dephtNormal = encodeDepthNormal(positionCS, normalWS);\n\n    gl_FragColor = dephtNormal;\n}';

  // src/layaAir/laya/d3/shader/pbr/PBRStandardShaderInit.ts
  var PBRStandardShaderInit = class {
    static init() {
      let uniformMap = {
        "u_AlbedoColor": 8 /* Color */,
        "u_TilingOffset": 6 /* Vector4 */,
        "u_NormalScale": 3 /* Float */,
        "u_Metallic": 3 /* Float */,
        "u_Smoothness": 3 /* Float */,
        "u_OcclusionStrength": 3 /* Float */,
        "u_AlphaTestValue": 3 /* Float */,
        "u_EmissionColor": 8 /* Color */,
        "u_EmissionIntensity": 3 /* Float */,
        "u_AlbedoTexture": 15 /* Texture2D */,
        "u_NormalTexture": 15 /* Texture2D */,
        "u_OcclusionTexture": 15 /* Texture2D */,
        "u_EmissionTexture": 15 /* Texture2D */,
        "u_MetallicGlossTexture": 15 /* Texture2D */,
        // anisotrioy
        "u_AnisotropyStrength": 3 /* Float */,
        "u_AnisotropyTexture": 15 /* Texture2D */,
        "u_AnisotropyRotation": 3 /* Float */,
        // clear coat
        "u_ClearCoatFactor": 3 /* Float */,
        "u_ClearCoatTexture": 15 /* Texture2D */,
        "u_ClearCoatRoughness": 3 /* Float */,
        "u_ClearCoatRoughnessTexture": 15 /* Texture2D */,
        "u_ClearCoatNormalTexture": 15 /* Texture2D */,
        //detail 
        "u_DetailAlbedoTexture": 15 /* Texture2D */,
        "u_DetailNormalTexture": 15 /* Texture2D */,
        "u_DetailNormalScale": 3 /* Float */,
        "u_DetailTillingOffset": 6 /* Vector4 */
      };
      let defaultValue = {
        "u_AlbedoColor": Color.WHITE,
        "u_TilingOffset": new Vector4(1, 1, 0, 0),
        "u_DetailTillingOffset": new Vector4(1, 1, 0, 0),
        "u_NormalScale": 1,
        "u_DetailNormalScale": 1,
        "u_Metallic": 0,
        "u_Smoothness": 0.5,
        "u_OcclusionStrength": 1,
        "u_EmissionColor": Color.WHITE,
        "u_EmissionIntensity": 1,
        "u_AlphaTestValue": 0.5,
        // anisotrioy
        "u_AnisotropyStrength": 0,
        "u_AnisotropyRotation": 0,
        // clear coat
        "u_ClearCoatFactor": 0,
        "u_ClearCoatRoughness": 0
      };
      let shader = Shader3D.add("PBR", true, true);
      shader.shaderType = 1 /* D3 */;
      shader._supportVolumetricGI = true;
      let subShader = new SubShader(SubShader.DefaultAttributeMap, uniformMap, defaultValue);
      shader.addSubShader(subShader);
      let shadingPass = subShader.addShaderPass(pbrStandard_default, pbrStandard_default2);
      let shadowPass = subShader.addShaderPass(Depth_default, Depth_default2, "ShadowCaster");
      let depthNormal = subShader.addShaderPass(PBRStandardDepthNormal_default, PBRStandardDepthNormal_default2, "DepthNormal");
    }
  };

  // src/layaAir/laya/d3/shader/sky/SkyBox.vs
  var SkyBox_default = '#define SHADER_NAME SkyBoxVS\n\n#include "SkyCommon.glsl";\n\nvarying vec3 v_Texcoord;\n\nvoid main()\n{\n    // todo \u8FD9\u4E2A\u8F6C\u6362 \uFF1F\n    v_Texcoord = vec3(-a_Position.x, a_Position.yz); //\u8F6C\u6362\u5750\u6807\u7CFB\n\n    vec4 position = rotateAroundYInDegrees(a_Position, u_Rotation);\n    // gl_Position = getPositionCS(position.xyz);\n\n    gl_Position = u_SkyProjectionViewMat * position;\n\n    gl_Position = remapSkyPositionZ(gl_Position);\n}';

  // src/layaAir/laya/d3/shader/sky/SkyBox.fs
  var SkyBox_default2 = '#define SHADER_NAME SkyBoxFS\n\n#include "Color.glsl";\n\nvarying vec3 v_Texcoord;\n\nconst vec4 c_ColorSpace = vec4(4.59479380, 4.59479380, 4.59479380, 2.0);\n\nvoid main()\n{\n    vec3 uv = v_Texcoord;\n    vec4 cubeSampler = textureCube(u_CubeTexture, uv);\n#ifdef Gamma_u_CubeTexture\n    cubeSampler = gammaToLinear(cubeSampler);\n#endif // Gamma_u_CubeTexture\n\n    vec3 color = cubeSampler.rgb * u_TintColor.rgb * pow(u_Exposure, 2.2) * c_ColorSpace.rgb;\n\n    gl_FragColor = vec4(color, 1.0);\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}';

  // src/layaAir/laya/d3/shader/sky/SkyBoxShaderInit.ts
  var SkyBoxShaderInit = class {
    static init() {
      let attributeMap = {
        "a_Position": [VertexMesh.MESH_POSITION0, 6 /* Vector4 */]
      };
      let uniformMap = {
        "u_TintColor": 8 /* Color */,
        "u_Exposure": 3 /* Float */,
        "u_Rotation": 3 /* Float */,
        "u_CubeTexture": 17 /* TextureCube */
      };
      let defaultValue = {
        "u_TintColor": new Color(0.5, 0.5, 0.5, 0.5),
        "u_Exposure": 1,
        "u_Rotation": 0
      };
      let shader = Shader3D.add("SkyBox");
      shader.shaderType = 6 /* Sky */;
      let subShader = new SubShader(attributeMap, uniformMap, defaultValue);
      shader.addSubShader(subShader);
      let pass = subShader.addShaderPass(SkyBox_default, SkyBox_default2);
      pass.renderState.depthTest = RenderState.DEPTHTEST_LEQUAL;
      pass.renderState.cull = 2 /* Back */;
      pass.renderState.depthWrite = false;
      pass.renderState.stencilWrite = false;
      pass.statefirst = true;
    }
  };

  // src/layaAir/laya/d3/shader/sky/SkyProceduralShader.vs
  var SkyProceduralShader_default = `#define SHADER_NAME SkyProceduralVS

#include "SkyCommon.glsl";


#define OUTER_RADIUS 1.025
#define RAYLEIGH (mix(0.0, 0.0025, pow(u_AtmosphereThickness,2.5)))// Rayleigh constant Rayleigh\u4E3A\u591C\u7A7A\u5149\u548C\u6781\u5149\u4EAE\u5EA6\u5355\u4F4D
#define MIE 0.0010             // Mie constant \u7C73\u6C0F\u6563\u5C04
#define SUN_BRIGHTNESS 20.0    // Sun brightness
#define MAX_SCATTER 50.0 // Maximum scattering value, to prevent math overflows on Adrenos

const float SKY_GROUND_THRESHOLD = 0.02;
const float outerRadius = OUTER_RADIUS;
const float outerRadius2 = OUTER_RADIUS*OUTER_RADIUS;
const float innerRadius = 1.0;
const float innerRadius2 = 1.0;
const float cameraHeight = 0.0001;

const float HDSundiskIntensityFactor = 15.0;
const float simpleSundiskIntensityFactor = 27.0;

const float sunScale = 400.0 * SUN_BRIGHTNESS;
const float kmESun = MIE * SUN_BRIGHTNESS;
const float km4PI = MIE * 4.0 * 3.14159265;
const float scale = 1.0 / (OUTER_RADIUS - 1.0);
const float scaleDepth = 0.25;
const float scaleOverScaleDepth = (1.0 / (OUTER_RADIUS - 1.0)) / 0.25;
const float samples = 2.0; // THIS IS UNROLLED MANUALLY, DON'T TOUCH

// RGB wavelengths        .35 (.62=158), .43 (.68=174), .525 (.75=190)
const vec3 c_DefaultScatteringWavelength = vec3(0.65, 0.57, 0.475);//\u9ED8\u8BA4\u6563\u5C04\u6CE2\u957F
const vec3 c_VariableRangeForScatteringWavelength = vec3(0.15, 0.15, 0.15);//\u6563\u5C04\u64AD\u653E\u7684\u53EF\u53D8\u8303\u56F4

varying vec3 v_GroundColor;
varying vec3 v_SkyColor;

#ifdef SUN_HIGH_QUALITY
	varying vec3 v_Vertex;
#elif defined(SUN_SIMPLE)
	varying vec3 v_RayDir;
#else
	varying float v_SkyGroundFactor;
#endif

#if defined(SUN_HIGH_QUALITY)||defined(SUN_SIMPLE)
	varying vec3 v_SunColor;
#endif

// Calculates the Rayleigh phase function
float getRayleighPhase(vec3 light, vec3 ray) 
{
	float eyeCos = dot(light, ray);
	return 0.75 + 0.75*eyeCos*eyeCos;
}

float scaleAngle(float inCos)
{
	float x = 1.0 - inCos;
	return 0.25 * exp(-0.00287 + x*(0.459 + x*(3.83 + x*(-6.80 + x*5.25))));
}


void main(){
    gl_Position = u_SkyProjectionViewMat*a_Position;

    vec3 skyTintInGammaSpace = pow(u_SkyTint.xyz,vec3(0.45));//u_SkyTint.xyz;//\u652F\u6301\u975EGAMMA\u7A7A\u95F4\u540E\u8981\u8C03\u6574
	vec3 scatteringWavelength = mix(c_DefaultScatteringWavelength-c_VariableRangeForScatteringWavelength,c_DefaultScatteringWavelength+c_VariableRangeForScatteringWavelength,vec3(1.0) - skyTintInGammaSpace); // using Tint in sRGB+ gamma allows for more visually linear interpolation and to keep (0.5) at (128, gray in sRGB) point
	vec3 invWavelength = 1.0 / pow(scatteringWavelength, vec3(4.0));

	float krESun = RAYLEIGH * SUN_BRIGHTNESS;
	float kr4PI = RAYLEIGH * 4.0 * 3.14159265;

	vec3 cameraPos = vec3(0.0,innerRadius + cameraHeight,0.0); // The camera's current position

	// Get the ray from the camera to the vertex and its length (which is the far point of the ray passing through the atmosphere)
	vec3 eyeRay = normalize(a_Position.xyz);

	float far = 0.0;
	vec3 cIn, cOut;
	if (eyeRay.y >= 0.0) {// Sky
		// Calculate the length of the "atmosphere"
		far = sqrt(outerRadius2 + innerRadius2 * eyeRay.y * eyeRay.y - innerRadius2) - innerRadius * eyeRay.y;

		// Calculate the ray's starting position, then calculate its scattering offset
		float height = innerRadius + cameraHeight;
		float depth = exp(scaleOverScaleDepth * -cameraHeight);
		float startAngle = dot(eyeRay, cameraPos) / height;
		float startOffset = depth*scaleAngle(startAngle);

		// Initialize the scattering loop variables
		float sampleLength = far / samples;
		float scaledLength = sampleLength * scale;
		vec3 sampleRay = eyeRay * sampleLength;
		vec3 samplePoint = cameraPos + sampleRay * 0.5;

		vec3 frontColor = vec3(0.0);
		//unrolling this manually to avoid some platform for loop slow
		{
			float height = length(samplePoint);
			float depth = exp(scaleOverScaleDepth * (innerRadius - height));
			float lightAngle = dot(-u_SunLight_direction, samplePoint) / height;
			float cameraAngle = dot(eyeRay, samplePoint) / height;
			float scatter = (startOffset + depth*(scaleAngle(lightAngle) - scaleAngle(cameraAngle)));
			vec3 attenuate = exp(-clamp(scatter, 0.0, MAX_SCATTER) * (invWavelength * kr4PI + km4PI));

			frontColor += attenuate * (depth * scaledLength);
			samplePoint += sampleRay;
		}
		{
			float height = length(samplePoint);
			float depth = exp(scaleOverScaleDepth * (innerRadius - height));
			float lightAngle = dot(-u_SunLight_direction, samplePoint) / height;
			float cameraAngle = dot(eyeRay, samplePoint) / height;
			float scatter = (startOffset + depth*(scaleAngle(lightAngle) - scaleAngle(cameraAngle)));
			vec3 attenuate = exp(-clamp(scatter, 0.0, MAX_SCATTER) * (invWavelength * kr4PI + km4PI));

			frontColor += attenuate * (depth * scaledLength);
			samplePoint += sampleRay;
		}

		// Finally, scale the Mie and Rayleigh colors and set up the varying variables for the pixel shader
		cIn = frontColor * (invWavelength * krESun);
		cOut = frontColor * kmESun;
	} else {// Ground
		far = (-cameraHeight) / (min(-0.001, eyeRay.y));
		vec3 pos = cameraPos + far * eyeRay;

		// Calculate the ray's starting position, then calculate its scattering offset
		float depth = exp((-cameraHeight) * (1.0/scaleDepth));
		float cameraAngle = dot(-eyeRay, pos);
		float lightAngle = dot(-u_SunLight_direction, pos);
		float cameraScale = scaleAngle(cameraAngle);
		float lightScale = scaleAngle(lightAngle);
		float cameraOffset = depth*cameraScale;
		float temp = lightScale + cameraScale;

		// Initialize the scattering loop variables
		float sampleLength = far / samples;
		float scaledLength = sampleLength * scale;
		vec3 sampleRay = eyeRay * sampleLength;
		vec3 samplePoint = cameraPos + sampleRay * 0.5;

		// Now loop through the sample rays
		vec3 frontColor = vec3(0.0, 0.0, 0.0);
		vec3 attenuate;

		// Loop removed because we kept hitting SM2.0 temp variable limits. Doesn't affect the image too much.
		{
			float height = length(samplePoint);
			float depth = exp(scaleOverScaleDepth * (innerRadius - height));
			float scatter = depth*temp - cameraOffset;
			attenuate = exp(-clamp(scatter, 0.0, MAX_SCATTER) * (invWavelength * kr4PI + km4PI));
			frontColor += attenuate * (depth * scaledLength);
			samplePoint += sampleRay;
		}

		cIn = frontColor * (invWavelength * krESun + kmESun);
		cOut = clamp(attenuate, 0.0, 1.0);
	}

	#ifdef SUN_HIGH_QUALITY
		v_Vertex = -a_Position.xyz;
	#elif defined(SUN_SIMPLE) 
		v_RayDir = -eyeRay;
	#else
		v_SkyGroundFactor = -eyeRay.y / SKY_GROUND_THRESHOLD;
	#endif

	// if we want to calculate color in vprog:
	// in case of linear: multiply by _Exposure in here (even in case of lerp it will be common multiplier, so we can skip mul in fshader)
	v_GroundColor = u_Exposure * (cIn + u_GroundTint.xyz * cOut);//u_GroundColor*u_GroundColor is gamma space convert to linear space
	v_SkyColor    = u_Exposure * (cIn * getRayleighPhase(-u_SunLight_direction, -eyeRay));

	
	// The sun should have a stable intensity in its course in the sky. Moreover it should match the highlight of a purely specular material.
	// This matching was done using the Unity3D standard shader BRDF1 on the 5/31/2017
	// Finally we want the sun to be always bright even in LDR thus the normalization of the lightColor for low intensity.
	float lightColorIntensity = clamp(length(u_SunLight_color.xyz), 0.25, 1.0);

	#ifdef SUN_HIGH_QUALITY 
		v_SunColor = HDSundiskIntensityFactor * clamp(cOut,0.0,1.0) * u_SunLight_color.xyz / lightColorIntensity;
	#elif defined(SUN_SIMPLE) 
		v_SunColor = simpleSundiskIntensityFactor * clamp(cOut * sunScale,0.0,1.0) * u_SunLight_color.xyz / lightColorIntensity;
	#endif
	gl_Position= remapSkyPositionZ(gl_Position);
}`;

  // src/layaAir/laya/d3/shader/sky/SkyProceduralShader.fs
  var SkyProceduralShader_default2 = '#define SHADER_NAME SkyProceduralFS\n\n#include "Color.glsl";\n\nconst float MIE_G = -0.990;\nconst float MIE_G2 = 0.9801;\nconst float SKY_GROUND_THRESHOLD = 0.02;\n\n// uniform float u_SunSize;\n// uniform float u_SunSizeConvergence;\n\nuniform vec3 u_SunLight_direction;\n\nvarying vec3 v_GroundColor;\nvarying vec3 v_SkyColor;\n\n#ifdef SUN_HIGH_QUALITY\nvarying vec3 v_Vertex;\n#elif defined(SUN_SIMPLE)\nvarying vec3 v_RayDir;\n#else\nvarying float v_SkyGroundFactor;\n#endif\n\n#if defined(SUN_HIGH_QUALITY) || defined(SUN_SIMPLE)\nvarying vec3 v_SunColor;\n#endif\n\n// Calculates the Mie phase function\nfloat getMiePhase(float eyeCos, float eyeCos2)\n{\n    float temp = 1.0 + MIE_G2 - 2.0 * MIE_G * eyeCos;\n    temp = pow(temp, pow(u_SunSize, 0.65) * 10.0);\n    temp = max(temp, 1.0e-4); // prevent division by zero, esp. in half precision\n    temp = 1.5 * ((1.0 - MIE_G2) / (2.0 + MIE_G2)) * (1.0 + eyeCos2) / temp;\n    return temp;\n}\n\n// Calculates the sun shape\nfloat calcSunAttenuation(vec3 lightPos, vec3 ray)\n{\n#ifdef SUN_HIGH_QUALITY\n    float focusedEyeCos = pow(clamp(dot(lightPos, ray), 0.0, 1.0), u_SunSizeConvergence);\n    return getMiePhase(-focusedEyeCos, focusedEyeCos * focusedEyeCos);\n#else // SUN_SIMPLE\n    vec3 delta = lightPos - ray;\n    float dist = length(delta);\n    float spot = 1.0 - smoothstep(0.0, u_SunSize, dist);\n    return spot * spot;\n#endif\n}\n\nvoid main()\n{\n    // if y > 1 [eyeRay.y < -SKY_GROUND_THRESHOLD] - ground\n    // if y >= 0 and < 1 [eyeRay.y <= 0 and > -SKY_GROUND_THRESHOLD] - horizon\n    // if y < 0 [eyeRay.y > 0] - sky\n    vec3 col = vec3(0.0, 0.0, 0.0);\n\n#ifdef SUN_HIGH_QUALITY\n    vec3 ray = normalize(v_Vertex);\n    float y = ray.y / SKY_GROUND_THRESHOLD;\n#elif defined(SUN_SIMPLE)\n    vec3 ray = v_RayDir;\n    float y = ray.y / SKY_GROUND_THRESHOLD;\n#else\n    float y = v_SkyGroundFactor;\n#endif\n\n    // if we did precalculate color in vprog: just do lerp between them\n    col = mix(v_SkyColor, v_GroundColor, clamp(y, 0.0, 1.0));\n\n#if defined(SUN_HIGH_QUALITY) || defined(SUN_SIMPLE)\n    if (y < 0.0)\n	col += v_SunColor * calcSunAttenuation(-u_SunLight_direction, -ray);\n#endif\n\n    // col = sqrt(col);//linear space convert to gamma space\n    gl_FragColor = vec4(col, 1.0);\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}\n';

