      this._targetVelocity = 0;
      /**@internal */
      this._freeSpin = false;
      /**@internal */
      this._limit = false;
      /**@internal */
      this._lowerLimit = -Math.PI / 2;
      /**@internal */
      this._uperLimit = Math.PI / 2;
