  var ExternalSkin = class {
    /**
     * @en The source of the external skin Spine.
     * @zh 外部皮肤spine的源。
     */
    get source() {
      return this._source;
    }
    set source(value) {
      this._source = value;
      if (value) {
        ILaya.loader.load(value, Loader.SPINE).then((templet) => {
          if (!this._source || templet && !templet.isCreateFromURL(this._source))
            return;
          this.templet = templet;
        });
      } else
        this.templet = null;
    }
    /**
     * @en The content of the external skin.
     * @zh 要设置的外部皮肤的内容。
     */
    get items() {
      return this._items;
    }
    set items(value) {
      this._items = value;
    }
    /**
     * @en Get the reference of the animation template.
     * @zh 得到动画模板的引用。
     */
    get templet() {
      return this._templet;
    }
    set templet(value) {
      this.init(value);
    }
    /**
     * @en Initialize the external skin with a given template.
     * @param templet The animation template reference.
     * @zh 使用给定的模板初始化外部皮肤。
     * @param templet 动画模板的引用。
     */
    init(templet) {
      this._templet = templet;
      if (!this._templet) {
        return;
      }
      this.flush();
    }
    /**
     * @en Replace the external skin Spine.
     * @zh 替换外部皮肤 Spine。
     */
    flush() {
      let targetTemplet = this.target?.templet;
      if (this._items && this._templet && targetTemplet && targetTemplet._textures) {
        let optimize = this._templet.optimize;
        if (!optimize)
          return;
        for (let i = this._items.length - 1; i >= 0; i--) {
          let o = this._items[i];
          this.target.setTempletAttachment(this._templet, o.slot, o.skin, o.attachment);
        }
      }
    }
  };

